const rtdal002824Source0007 = `secret_decrypt_file <- function(path, key, envir = parent.frame()) {
  enc <- readBin(path, "raw", file.size(path))
  dec <- secret_decrypt_raw(enc, key = key)

  path <- tempfile()
  withr::defer(unlink(path), envir)
  writeBin(dec, path)
  Sys.chmod(path, 400)
  path
}`

const rtdal002824Source0010 = `secret_get_key <- function(envvar, call = caller_env()) {
  key <- Sys.getenv(envvar)

  if (identical(key, "")) {
    msg <- glue("Can't find envvar {envvar}")
    if (is_testing()) {
      testthat::skip(msg)
    } else {
      abort(msg, call = call)
    }
  }

  base64_url_decode(key)
}`

const rtdal002824Source0012 = `attr(obfuscate, "srcref") <- "function(x) {}"`

const rtdal002824Source0014 = `str.httr2_obfuscated <- function(object, ...) {
  cat(" ", glue('obfuscated("{object}")\n'), sep = "")
}`

const rtdal002824Source0015 = `print.httr2_obfuscated <- function(x, ...) {
  cat(glue('obfuscated("{x}")\n'))
  invisible(x)
}`

const rtdal002824Source0017 = `unobfuscate_rec <- function(x, handle = "reveal") {
  if (is_obfuscated(x)) {
    switch(
      handle,
      reveal = secret_decrypt(x, obfuscate_key()),
      redact = "<REDACTED>",
      remove = NULL
    )
  } else if (is.list(x)) {
    x[] <- lapply(x, unobfuscate, handle = handle)
    x
  } else {
    x
  }
}`

