const rtdal002896Source0001 = `test_that("can handle multi query params", {
  expect_equal(
    multi_dots(a = 1:2, .multi = "explode"),
    list(a = I("1"), a = I("2"))
  )
  expect_equal(
    multi_dots(a = 1:2, .multi = "comma"),
    list(a = I("1,2"))
  )
  expect_equal(
    multi_dots(a = 1:2, .multi = "pipe"),
    list(a = I("1|2"))
  )
  expect_equal(
    multi_dots(a = 1:2, .multi = function(x) "X"),
    list(a = I("X"))
  )
})`

const rtdal002896Source0002 = `test_that("can handle mixed length multi query params", {
  expect_equal(
    multi_dots(a = 1:2, b = 1, c = NULL, .multi = "explode"),
    list(a = I("1"), a = I("2"), b = I("1"), c = NULL)
  )
  expect_equal(
    multi_dots(a = 1:2, b = 1, c = NULL, .multi = "comma"),
    list(a = I("1,2"), b = I("1"), c = NULL)
  )
  expect_equal(
    multi_dots(a = 1:2, b = 1, c = NULL, .multi = "pipe"),
    list(a = I("1|2"), b = I("1"), c = NULL)
  )
  expect_equal(
    multi_dots(a = 1:2, b = 1, c = NULL, .multi = function(x) "X"),
    list(a = I("X"), b = I("1"), c = NULL)
  )
})`

const rtdal002896Source0003 = `test_that("can opt-out of escaping for' vectors", {
  expect_equal(
    multi_dots(a = I(c(" ", " ")), .multi = "comma"),
    list(a = I(" , "))
  )
})`

const rtdal002896Source0004 = `test_that("can handle empty dots", {
  expect_equal(multi_dots(), list())
})`

const rtdal002896Source0005 = `test_that("preserves NULL values", {
  expect_equal(multi_dots(x = NULL), list(x = NULL))
})`

const rtdal002896Source0006 = `test_that("preserves duplicates values", {
  expect_equal(multi_dots(x = 1, x = 2), list(x = I("1"), x = I("2")))
})`

const rtdal002896Source0007 = `test_that("leaves already escaped values alone", {
  x <- I("1 + 2")
  expect_equal(multi_dots(x = x), list(x = x))
})`

const rtdal002896Source0008 = `test_that("checks its inputs", {
  expect_snapshot(error = TRUE, {
    multi_dots(1)
    multi_dots(x = I(1))
    multi_dots(x = 1:2)
    multi_dots(x = mean)
  })
})`

