const rtdal002913Source0085 = `hsbm_list_game_impl <- function(
  n,
  mlist,
  rholist,
  Clist,
  p
) {
  # Argument checks
  n <- as.numeric(n)
  mlist <- as.numeric(mlist)
  if (!is.list(Clist)) {
    cli::cli_abort("{.arg Clist} must be a list of matrices")
  }
  Clist <- lapply(Clist, function(m) {
    if (!is.matrix(m)) {
      cli::cli_abort("{.arg Clist} must be a list of matrices")
    }
    m[] <- as.numeric(m)
    m
  })
  p <- as.numeric(p)

  on.exit(.Call(R_igraph_finalizer))
  # Function call
  res <- .Call(
    R_igraph_hsbm_list_game,
    n,
    mlist,
    rholist,
    Clist,
    p
  )

  if (igraph_opt("add.params")) {
    res$name <- 'Hierarchical stochastic block model'
    res$p <- p
  }

  res
}`

