const rtdal002913Source0444 = `eigen_matrix_impl <- function(
  A,
  sA,
  fun,
  n,
  algorithm,
  which,
  options = arpack_defaults()
) {
  # Argument checks
  A[] <- as.numeric(A)
  requireNamespace("Matrix", quietly = TRUE)
  sA <- as(as(as(sA, "dMatrix"), "generalMatrix"), "CsparseMatrix")
  n <- as.integer(n)
  algorithm <- switch_igraph_arg(
    algorithm,
    "auto" = 0L,
    "lapack" = 1L,
    "arpack" = 2L,
    "comp_auto" = 3L,
    "comp_lapack" = 4L,
    "comp_arpack" = 5L
  )
  which.tmp <- eigen_defaults()
  which.tmp[names(which)] <- which
  which <- which.tmp
  options <- modify_list(arpack_defaults(), options)

  on.exit(.Call(R_igraph_finalizer))
  # Function call
  res <- .Call(
    R_igraph_eigen_matrix,
    A,
    sA,
    n,
    algorithm,
    which,
    options
  )

  res
}`

