const rtdal002913Source0486 = `community_leading_eigenvector_callback_closure_impl <- function(
  graph,
  weights = NULL,
  membership = NULL,
  steps = -1,
  options = arpack_defaults(),
  start = FALSE,
  callback = NULL,
  extra = NULL,
  env = parent.frame(),
  env_arp = environment(igraph.i.levc.arp)
) {
  # Argument checks
  ensure_igraph(graph)
  if (is.null(weights) && "weight" %in% edge_attr_names(graph)) {
    weights <- E(graph)$weight
  }
  if (!is.null(weights) && !all(is.na(weights))) {
    weights <- as.numeric(weights)
  } else {
    weights <- NULL
  }
  if (!is.null(membership)) {
    membership <- as.numeric(membership)
  }
  steps <- as.numeric(steps)
  options <- modify_list(arpack_defaults(), options)
  start <- as.logical(start)
  if (!is.null(callback)) {
    if (!is.function(callback)) {
      cli::cli_abort("{.arg callback} must be a function")
    }
    callback_wrapped <- function(...) {
      tryCatch(
        {
          out <- callback(...)
          if (is.logical(out) && length(out) == 1 && !is.na(out)) {
            out
          } else {
            rlang::error_cnd(message = "Callback returned a value different from TRUE or FALSE")
          }
        },
        error = function(e) e,
        interrupt = function(e) e
      )
    }
  } else {
    callback_wrapped <- NULL
  }


  on.exit(.Call(R_igraph_finalizer))
  # Function call
  res <- .Call(
    R_igraph_community_leading_eigenvector_callback_closure,
    graph,
    weights,
    membership,
    steps,
    options,
    start,
    callback_wrapped,
    extra,
    env,
    env_arp
  )

  class(res) <- "igraph.eigenc"
  res
}`

