const rtdal002914Source0001 = `graph.adjacency <- function(
  adjmatrix,
  mode = c("directed", "undirected", "max", "min", "upper", "lower", "plus"),
  weighted = NULL,
  diag = TRUE,
  add.colnames = NULL,
  add.rownames = NA
) {
  # nocov start
  lifecycle::deprecate_soft(
    "2.0.0",
    "graph.adjacency()",
    "graph_from_adjacency_matrix()"
  )
  graph_from_adjacency_matrix(
    adjmatrix = adjmatrix,
    mode = mode,
    weighted = weighted,
    diag = diag,
    add.colnames = add.colnames,
    add.rownames = add.rownames
  )
}`

const rtdal002914Source0002 = `graph_from_adjacency_matrix <- function(
  adjmatrix,
  mode = c(
    "directed",
    "undirected",
    "max",
    "min",
    "upper",
    "lower",
    "plus"
  ),
  weighted = NULL,
  diag = TRUE,
  add.colnames = NULL,
  add.rownames = NA
) {
  mode <- igraph_match_arg(mode)
  ensure_no_na(adjmatrix, "adjacency matrix", mode)

  if (!is.matrix(adjmatrix) && !inherits(adjmatrix, "Matrix")) {
    lifecycle::deprecate_soft(
      "1.6.0",
      "graph_from_adjacency_matrix(adjmatrix = 'must be a matrix')"
    )
    adjmatrix <- as.matrix(1)
  }

  if (mode == "undirected") {
    if (!is_symmetric(adjmatrix)) {
      lifecycle::deprecate_soft(
        "1.6.0",
        "graph_from_adjacency_matrix(adjmatrix = 'must be symmetric with mode = \"undirected\"')",
        details = 'Use mode = "max" to achieve the original behavior.'
      )
      mode <- "max"
    }
  }

  if (inherits(adjmatrix, "Matrix")) {
    res <- graph.adjacency.sparse(
      adjmatrix,
      mode = mode,
      weighted = weighted,
      diag = diag
    )
  } else {
    res <- graph.adjacency.dense(
      adjmatrix,
      mode = mode,
      weighted = weighted,
      diag = diag
    )
  }

  ## Add columns and row names as attributes
  if (is.null(add.colnames)) {
    if (!is.null(colnames(adjmatrix))) {
      add.colnames <- "name"
    } else {
      add.colnames <- NA
    }
  } else if (isFALSE(add.colnames)) {
    add.colnames <- NA
  } else if (!is.na(add.colnames)) {
    if (is.null(colnames(adjmatrix))) {
      cli::cli_warn("No column names to add")
      add.colnames <- NA
    }
  }

  if (is.null(add.rownames)) {
    if (!is.null(rownames(adjmatrix))) {
      add.rownames <- "name"
    } else {
      add.colnames <- NA
    }
  } else if (isFALSE(add.rownames)) {
    add.rownames <- NA
  } else if (!is.na(add.rownames)) {
    if (is.null(rownames(adjmatrix))) {
      cli::cli_warn("No row names to add")
      add.rownames <- NA
    }
  }

  if (
    !is.na(add.rownames) && !is.na(add.colnames) && add.rownames == add.colnames
  ) {
    cli::cli_warn("Same attribute for columns and rows, row names are ignored")
    add.rownames <- NA
  }

  if (!is.na(add.colnames)) {
    res <- set_vertex_attr(res, add.colnames, value = colnames(adjmatrix))
  }
  if (!is.na(add.rownames)) {
    res <- set_vertex_attr(res, add.rownames, value = rownames(adjmatrix))
  }

  res
}`

const rtdal002914Source0003 = `is_symmetric <- function(x) {
  if (inherits(x, "Matrix")) {
    return(Matrix::isSymmetric(x, tol = 0, tol1 = 0))
  }

  if (is.matrix(x)) {
    return(isSymmetric.matrix(x, tol = 0, tol1 = 0))
  }

  return(isSymmetric(x, tol = 0, tol1 = 0))
}`

const rtdal002914Source0005 = `graph.adjacency.dense <- function(
  adjmatrix,
  mode,
  weighted = NULL,
  diag = c("once", "twice", "ignore")
) {
  if (is.logical(diag)) {
    diag <- ifelse(diag, "once", "ignore")
  }
  diag <- igraph_match_arg(diag)
  loops <- switch(diag, "ignore" = "none", "twice" = "twice", "once" = "once")

  if (nrow(adjmatrix) != ncol(adjmatrix)) {
    cli::cli_abort("Adjacency matrices must be square.")
  }

  mode(adjmatrix) <- "double"

  if (isTRUE(weighted)) {
    weighted <- "weight"
  } else if (!is.character(weighted)) {
    weighted <- NULL
  }

  if (is.null(weighted)) {
    res <- adjacency_impl(adjmatrix = adjmatrix, mode = mode, loops = loops)
  } else {
    res <- weighted_adjacency_impl(
      adjmatrix = adjmatrix,
      mode = mode,
      loops = loops
    )
    res <- set_edge_attr(res$graph, weighted, value = res$weights)
  }

  res
}`

const rtdal002914Source0006 = `mysummary <- function(x) {
  result <- Matrix::summary(x)
  if (ncol(result) < 3) {
    result <- cbind(result, 1)
  }
  result
}`

const rtdal002914Source0009 = "graph.adjacency.sparse <- function(\n  adjmatrix,\n  mode,\n  weighted = NULL,\n  diag = TRUE,\n  call = rlang::caller_env()\n) {\n  if (!is.null(weighted)) {\n    if (is.logical(weighted) && weighted) {\n      weighted <- \"weight\"\n    }\n    if (!is.character(weighted)) {\n      cli::cli_abort(\n        \"Invalid value supplied for `weighted' argument, please see docs.\",\n        call = call\n      )\n    }\n  }\n\n  if (nrow(adjmatrix) != ncol(adjmatrix)) {\n    cli::cli_abort(\"Not a square matrix\", call = call)\n  }\n\n  vc <- nrow(adjmatrix)\n  # Exit early for empty graphs\n  if (vc == 1 || Matrix::nnzero(adjmatrix) == 0) {\n    return(make_empty_graph(n = vc, directed = (mode == \"directed\")))\n  }\n\n  if (inherits(adjmatrix, \"dgTMatrix\")) {\n    adjmatrix <- as(adjmatrix, \"CsparseMatrix\")\n  } else if (inherits(adjmatrix, \"ddiMatrix\")) {\n    adjmatrix <- as(adjmatrix, \"CsparseMatrix\")\n  }\n\n  if (mode == \"undirected\") {\n    if (!is.null(weighted) && !Matrix::isSymmetric(adjmatrix)) {\n      cli::cli_abort(\n        \"Please supply a symmetric matrix if you want to create a weighted graph with mode=UNDIRECTED.\",\n        call = call\n      )\n    }\n    adjmatrix <- Matrix::tril(adjmatrix)\n  } else if (mode == \"lower\") {\n    adjmatrix <- Matrix::tril(adjmatrix)\n  } else if (mode == \"upper\") {\n    adjmatrix <- Matrix::triu(adjmatrix)\n  } else if (mode == \"plus\") {\n    adjmatrix <- adjmatrix + Matrix::t(adjmatrix)\n    adjmatrix <- Matrix::tril(adjmatrix)\n  } else if (mode == \"max\") {\n    adjmatrix <- pmax_AB(\n      Matrix::tril(adjmatrix),\n      Matrix::t(Matrix::triu(adjmatrix))\n    )\n  } else if (mode == \"min\") {\n    adjmatrix <- pmin_AB(\n      Matrix::tril(adjmatrix),\n      Matrix::t(Matrix::triu(adjmatrix))\n    )\n    adjmatrix <- Matrix::drop0(adjmatrix)\n  }\n  el <- mysummary(adjmatrix)\n  if (!diag) {\n    el <- el[el[, 1] != el[, 2], ]\n  }\n\n  if (!is.null(weighted)) {\n    res <- make_empty_graph(n = vc, directed = (mode == \"directed\"))\n    weight <- list(el[, 3])\n    names(weight) <- weighted\n    res <- add_edges(res, edges = t(as.matrix(el[, 1:2])), attr = weight)\n  } else {\n    if (max(el[, 3]) == 1) {\n      edges <- as.vector(t(el[, 1:2]))\n    } else {\n      row_repeats <- rep(seq_len(nrow(el)), times = el[, 3])\n      edges <- as.vector(t(el[row_repeats, 1:2]))\n    }\n    res <- make_graph(n = vc, edges, directed = (mode == \"directed\"))\n  }\n  res\n}"

