const rtdal002917Source0024 = "set_vertex_attrs <- function(graph, ..., index = V(graph)) {\n  call <- rlang::current_env()\n  dots <- rlang::list2(...)\n\n  if (!rlang::is_named(dots)) {\n    cli::cli_abort(\"All arguments in `...` must be named.\")\n  }\n\n  for (attr_name in names(dots)) {\n    attr_value <- dots[[attr_name]]\n    graph <- i_set_vertex_attr(\n      graph,\n      name = attr_name,\n      index = index,\n      value = attr_value,\n      call = call\n    )\n  }\n\n  graph\n}"

const rtdal002917Source0025 = `i_set_vertex_attr <- function(
  graph,
  name,
  index = V(graph),
  value,
  check = TRUE,
  call = rlang::caller_env()
) {
  ensure_igraph(graph)
  check_string(name)

  if (is.null(value)) {
    return(graph)
  }

  # https://github.com/igraph/rigraph/issues/807
  # Checks if any of those classes is inherited from
  if (inherits(value, c("igraph.vs", "igraph.es"))) {
    value <- as.numeric(value)
  }

  if (!missing(index) && check) {
    index <- as_igraph_vs(graph, index)
  }

  vattrs <- .Call(
    Rx_igraph_mybracket2,
    graph,
    igraph_t_idx_attr,
    igraph_attr_idx_vertex
  )

  complete <- is_complete_iterator(index)
  name_available <- (name %in% names(vattrs))
  if (!complete && !name_available) {
    vattrs[[name]] <- value[rep.int(NA_integer_, vcount(graph))]
  }

  single <- is_single_index(index)
  if (single) {
    vattrs[[name]][[index]] <- value
  } else {
    if (length(value) == 1) {
      value_in <- rep(unname(value), length(index))
    } else if (length(value) == length(index)) {
      value_in <- unname(value)
    } else {
      cli::cli_abort(
        "Length of new attribute value must be {if (length(index) != 1) '1 or '}{length(index)}, the number of target vertices, not {length(value)}.",
        call = call
      )
    }

    if (complete) {
      vattrs[[name]] <- value_in
    } else {
      vattrs[[name]][index] <- value_in
    }
  }

  .Call(
    Rx_igraph_mybracket2_set,
    graph,
    igraph_t_idx_attr,
    igraph_attr_idx_vertex,
    vattrs
  )
}`

const rtdal002917Source0027 = `set_value_at <- function(value, idx, length_out) {
  out <- value[NULL]
  length(out) <- length_out
  out[idx] <- value
  unname(out)
}`

const rtdal002917Source0028 = `"vertex.attributes<-" <- function(graph, index = V(graph), value) {
  ensure_igraph(graph)

  assert_named_list(value)
  if (inherits(value, "data.frame")) {
    value <- as.list(value)
  }

  if (!all(lengths(value) == length(index))) {
    cli::cli_abort(
      "Invalid attribute value length, must match number of vertices."
    )
  }

  if (!missing(index)) {
    index <- as_igraph_vs(graph, index)

    if (anyDuplicated(index) || anyNA(index)) {
      cli::cli_abort("{.arg index} contains duplicated vertices or NAs.")
    }
  }

  if (
    !missing(index) &&
      !index_is_natural_vertex_sequence(index, graph)
  ) {
    value <- map(
      value,
      set_value_at,
      idx = index,
      length_out = length(V(graph))
    )
  }

  .Call(
    Rx_igraph_mybracket2_set,
    graph,
    igraph_t_idx_attr,
    igraph_attr_idx_vertex,
    value
  )
}`

const rtdal002917Source0029 = `edge_attr <- function(graph, name, index = E(graph)) {
  ensure_igraph(graph)

  if (missing(name)) {
    if (missing(index)) {
      edge.attributes(graph)
    } else {
      edge.attributes(graph, index = index)
    }
  } else {
    check_string(name)
    myattr <- .Call(
      Rx_igraph_mybracket2,
      graph,
      igraph_t_idx_attr,
      igraph_attr_idx_edge
    )[[name]]
    if (is_complete_iterator(index)) {
      myattr
    } else {
      index <- as_igraph_es(graph, index)
      myattr[index]
    }
  }
}`

