const rtdal002922Source0009 = `cliques <- function(graph, min = NULL, max = NULL, ..., callback = NULL) {
  ensure_igraph(graph)
  check_dots_empty()

  if (is.null(callback)) {
    # Collector mode: use original implementation
    cliques_impl(
      graph = graph,
      min = min %||% 0,
      max = max %||% 0
    )
  } else {
    # Callback mode: call user function
    cliques_callback_closure_impl(
      graph = graph,
      min_size = min %||% 0,
      max_size = max %||% 0,
      callback = callback
    )
    invisible(NULL)
  }
}`

const rtdal002922Source0011 = `max_cliques <- function(
  graph,
  min = NULL,
  max = NULL,
  subset = NULL,
  file = NULL,
  ...,
  callback = NULL
) {
  ensure_igraph(graph)
  check_dots_empty()

  # Handle file and subset modes (original functionality)
  if (!is.null(file)) {
    if (
      !is.character(file) ||
        length(grep("://", file, fixed = TRUE)) > 0 ||
        length(grep("~", file, fixed = TRUE)) > 0
    ) {
      tmpfile <- TRUE
      origfile <- file
      file <- tempfile()
    } else {
      tmpfile <- FALSE
    }
    on.exit(.Call(Rx_igraph_finalizer))
    res <- .Call(
      Rx_igraph_maximal_cliques_file,
      graph,
      subset,
      file,
      as.numeric(min %||% 0),
      as.numeric(max %||% 0)
    )
    if (tmpfile) {
      buffer <- read.graph.toraw(file)
      write.graph.fromraw(buffer, origfile)
    }
    return(invisible(NULL))
  }

  # Collector or callback mode
  if (is.null(callback)) {
    # Collector mode: use original implementation
    if (is.null(subset)) {
      subset_arg <- NULL
    } else {
      subset_arg <- as.numeric(as_igraph_vs(graph, subset) - 1)
    }

    on.exit(.Call(Rx_igraph_finalizer))
    res <- .Call(
      Rx_igraph_maximal_cliques,
      graph,
      subset_arg,
      as.numeric(min %||% 0),
      as.numeric(max %||% 0)
    )
    res <- lapply(res, function(x) x + 1)

    if (igraph_opt("return.vs.es")) {
      res <- lapply(res, unsafe_create_vs, graph = graph, verts = V(graph))
    }

    res
  } else {
    # Callback mode: call user function
    if (!is.null(subset)) {
      cli::cli_abort(
        "{.arg subset} is not supported when {.arg callback} is provided"
      )
    }

    maximal_cliques_callback_closure_impl(
      graph = graph,
      min_size = min %||% 0,
      max_size = max %||% 0,
      callback = callback
    )
    invisible(NULL)
  }
}`

const rtdal002922Source0020 = `maximal_ivs <- function(graph) {
  lifecycle::deprecate_soft("2.1.0", "maximal_ivs()", "max_ivs()")
  max_ivs(graph)
}`

const rtdal002922Source0023 = `clique_size_counts <- function(graph, min = 0, max = 0, maximal = FALSE) {
  if (maximal) {
    maximal_cliques_hist_impl(
      graph = graph,
      min_size = min,
      max_size = max
    )
  } else {
    clique_size_hist_impl(
      graph = graph,
      min_size = min,
      max_size = max
    )
  }
}`

