const rtdal002924Source0007 = `cohesive_blocks <- function(graph, labels = TRUE) {
  # Argument checks
  ensure_igraph(graph)

  res <- cohesive_blocks_impl(
    graph = graph
  )
  class(res) <- "cohesiveBlocks"
  if (labels && "name" %in% vertex_attr_names(graph)) {
    res$labels <- V(graph)$name
  }
  if (igraph_opt("return.vs.es")) {
    res$blocks <- lapply(
      res$blocks,
      unsafe_create_vs,
      graph = graph,
      verts = V(graph)
    )
  }

  res$vcount <- vcount(graph)
  res
}`

const rtdal002924Source0011 = `cohesion <- function(x, ...) {
  UseMethod("cohesion")
}`

const rtdal002924Source0012 = `cohesion.cohesiveBlocks <- function(x, ...) {
  x$cohesion
}`

const rtdal002924Source0015 = `print.cohesiveBlocks <- function(x, ...) {
  cat("Cohesive block structure:\n")
  myb <- blocks(x)
  ch <- cohesion(x)
  pp <- parent(x)
  si <- sapply(myb, length)

  cs <- 3 +
    2 +
    nchar(length(x)) +
    max(distances(hierarchy(x), mode = "out", v = 1)) * 3

  .plot <- function(b, ind = "") {
    if (b != 1) {
      he <- format(paste(sep = "", ind, "'- B-", b), width = cs)
      ind <- paste("  ", ind)
    } else {
      he <- format(paste(sep = "", "B-", b), width = cs)
    }
    cat(
      sep = "",
      he,
      "c ",
      format(ch[b], width = nchar(max(ch)), justify = "right"),
      ", n ",
      format(si[b], width = nchar(x$vcount), justify = "right")
    )

    if (x$vcount <= options("width")$width - 40 && b != 1) {
      o <- rep(".", x$vcount)
      o[myb[[b]]] <- "o"
      oo <- character()
      for (i in 1:floor(x$vcount / 10)) {
        oo <- c(oo, o[((i - 1) * 10 + 1):(i * 10)], " ")
      }
      if (x$vcount %% 10) {
        oo <- c(oo, o[(i * 10 + 1):length(o)])
      }
      cat("  ", paste(oo, collapse = ""), "\n")
    } else {
      cat("\n")
    }

    wc <- which(pp == b)
    sapply(wc, .plot, ind = ind)
  }
  if (length(x) > 0) {
    .plot(1)
  } else {
    cat("No cohesive blocks found.")
  }

  invisible(x)
}`

const rtdal002924Source0016 = `summary.cohesiveBlocks <- function(object, ...) {
  cat(
    "Structurally cohesive block structure, with",
    length(blocks(object)),
    "blocks.\n"
  )
  invisible(object)
}`

