const rtdal002926Source0037 = `as.phylo.communities <- function(x, use.modularity = FALSE, ...) {
  if (!is_hierarchical(x)) {
    cli::cli_abort("Not a hierarchical community structure")
  }

  ## If multiple components, then we merge them in arbitrary order
  merges <- complete.dend(x, use.modularity)

  if (!use.modularity || is.null(x$modularity)) {
    height <- 1:nrow(merges)
  } else {
    height <- x$modularity[-1]
    height <- cumsum(height - min(height))
  }

  if (is.null(x$names)) {
    labels <- 1:(nrow(merges) + 1)
  } else {
    labels <- x$names
  }

  N <- nrow(merges)
  edge <- matrix(0L, 2 * N, 2)
  edge.length <- numeric(2 * N)
  node <- integer(N)
  node[N] <- N + 2L
  cur.nod <- N + 3L
  j <- 1L
  for (i in N:1) {
    edge[j:(j + 1), 1] <- node[i]
    for (l in 1:2) {
      k <- j + l - 1L
      y <- merges[i, l]
      if (y > N + 1) {
        edge[k, 2] <- node[y - N - 1] <- cur.nod
        cur.nod <- cur.nod + 1L
        edge.length[k] <- height[i] - height[y - N - 1]
      } else {
        edge[k, 2] <- y
        edge.length[k] <- height[i]
      }
    }
    j <- j + 2L
  }

  obj <- list(
    edge = edge,
    edge.length = edge.length / 2,
    tip.label = labels,
    Nnode = N
  )
  class(obj) <- "phylo"
  ape::reorder.phylo(obj)
}`

const rtdal002926Source0038 = `rlang::on_load(s3_register("ape::as.phylo", "communities"))`

const rtdal002926Source0039 = `cut_at <- function(communities, no, steps) {
  if (!inherits(communities, "communities")) {
    cli::cli_abort("Not a community structure")
  }
  if (!is_hierarchical(communities)) {
    cli::cli_abort("Not a hierarchical communitity structure")
  }

  if (
    (!missing(no) && !missing(steps)) ||
      (missing(no) && missing(steps))
  ) {
    cli::cli_abort("Please use either {.arg no} or {.arg steps} (but not both)")
  }

  if (!missing(steps)) {
    mm <- merges(communities)
    if (steps > nrow(mm)) {
      cli::cli_warn("Cannot make that many steps.")
      steps <- nrow(mm)
    }
    community.to.membership2(mm, communities$vcount, steps)
  } else {
    mm <- merges(communities)
    noc <- communities$vcount - nrow(mm) # final number of communities
    if (no < noc) {
      cli::cli_warn("Cannot have that few communities.")
      no <- noc
    }
    steps <- communities$vcount - no
    community.to.membership2(mm, communities$vcount, steps)
  }
}`

const rtdal002926Source0040 = `show_trace <- function(communities) {
  if (!inherits(communities, "communities")) {
    cli::cli_abort("Not a community structure")
  }
  if (is.null(communities$history)) {
    cli::cli_abort("History was not recorded")
  }

  res <- character()
  i <- 1
  while (i <= length(communities$history)) {
    if (communities$history[i] == 2) {
      # IGRAPH_LEVC_HIST_SPLIT
      resnew <- paste(
        "Splitting community",
        communities$history[i + 1],
        "into two."
      )
      i <- i + 2
    } else if (communities$history[i] == 3) {
      # IGRAPH_LEVC_HIST_FAILED
      resnew <- paste(
        "Failed splitting community",
        communities$history[i + 1],
        "into two."
      )
      i <- i + 2
    } else if (communities$history[i] == 4) {
      # IGRAPH_LEVC_START_FULL
      resnew <- "Starting with the whole graph as a community."
      i <- i + 1
    } else if (communities$history[i] == 5) {
      # IGRAPH_LEVC_START_GIVEN
      resnew <- paste(
        "Starting from the",
        communities$history[i + 1],
        "given communities."
      )
      i <- i + 2
    }

    res <- c(res, resnew)
  }
  res
}`

