const rtdal002926Source0042 = `cluster_spinglass <- function(
  graph,
  weights = NULL,
  vertex = NULL,
  spins = 25,
  parupdate = FALSE,
  start.temp = 1,
  stop.temp = 0.01,
  cool.fact = 0.99,
  update.rule = c("config", "random", "simple"),
  gamma = 1.0,
  implementation = c("orig", "neg"),
  gamma.minus = 1.0
) {
  ensure_igraph(graph)

  if (is.null(weights) && "weight" %in% edge_attr_names(graph)) {
    weights <- E(graph)$weight
  }
  if (!is.null(weights) && any(!is.na(weights))) {
    weights <- as.numeric(weights)
  } else {
    weights <- NULL
  }

  update.rule <- igraph_match_arg(update.rule)
  update.rule <- switch(update.rule, "simple" = 0, "random" = 0, "config" = 1)
  implementation <- switch(
    igraph_match_arg(implementation),
    "orig" = 0,
    "neg" = 1
  )

  on.exit(.Call(Rx_igraph_finalizer))
  if (is.null(vertex) || length(vertex) == 0) {
    res <- .Call(
      Rx_igraph_spinglass_community,
      graph,
      weights,
      as.numeric(spins),
      as.logical(parupdate),
      as.numeric(start.temp),
      as.numeric(stop.temp),
      as.numeric(cool.fact),
      as.numeric(update.rule),
      as.numeric(gamma),
      as.numeric(implementation),
      as.numeric(gamma.minus)
    )
    res$algorithm <- "spinglass"
    res$vcount <- vcount(graph)
    res$membership <- res$membership + 1
    if (igraph_opt("add.vertex.names") && is_named(graph)) {
      res$names <- vertex_attr(graph, "name")
    }
    class(res) <- "communities"
  } else {
    res <- .Call(
      Rx_igraph_spinglass_my_community,
      graph,
      weights,
      as_igraph_vs(graph, vertex) - 1,
      as.numeric(spins),
      as.numeric(update.rule),
      as.numeric(gamma)
    )
    res$community <- res$community + 1
  }
  res
}`

const rtdal002926Source0043 = `cluster_leiden <- function(
  graph,
  objective_function = c("CPM", "modularity"),
  ...,
  weights = NULL,
  resolution = 1,
  resolution_parameter = deprecated(),
  beta = 0.01,
  initial_membership = NULL,
  n_iterations = 2,
  vertex_weights = NULL
) {
  check_dots_empty()

  if (lifecycle::is_present(resolution_parameter)) {
    lifecycle::deprecate_soft(
      "2.1.0",
      "cluster_leiden(resolution_parameter)",
      "cluster_leiden(resolution)"
    )
    resolution <- resolution_parameter
  }

  ensure_igraph(graph)

  # Parse objective function argument
  objective_function <- igraph_match_arg(objective_function)
  objective_function <- switch(objective_function, "cpm" = 0, "modularity" = 1)

  # Parse edge weights argument
  if (is.null(weights) && "weight" %in% edge_attr_names(graph)) {
    weights <- E(graph)$weight
  }
  if (!is.null(weights) && !any(is.na(weights))) {
    weights <- as.numeric(weights)
  } else {
    weights <- NULL
  }

  # Parse initial_membership argument
  if (!is.null(initial_membership) && !any(is.na(initial_membership))) {
    initial_membership <- as.numeric(initial_membership)
  } else {
    initial_membership <- NULL
  }

  # Parse node weights argument
  if (!is.null(vertex_weights) && !any(is.na(vertex_weights))) {
    vertex_weights <- as.numeric(vertex_weights)
    if (objective_function == 1) {
      # Using modularity
      cli::cli_warn("Providing node weights contradicts using modularity.")
    }
  } else {
    if (objective_function == 1) {
      # Using modularity
      # Set correct node weights
      vertex_weights <- strength(graph, weights = weights)
      # Also correct resolution parameter
      resolution <- resolution / sum(vertex_weights)
    }
  }

  membership <- initial_membership
  if (n_iterations > 0) {
    res <- community_leiden_impl(
      graph = graph,
      weights = weights,
      vertex_weights = vertex_weights,
      resolution = resolution,
      beta = beta,
      start = !is.null(membership),
      n_iterations = n_iterations,
      membership = membership
    )

    membership <- res$membership
  } else {
    prev_quality <- -Inf
    quality <- 0.0
    while (prev_quality < quality) {
      prev_quality <- quality
      res <- community_leiden_impl(
        graph = graph,
        weights = weights,
        vertex_weights = vertex_weights,
        resolution = resolution,
        beta = beta,
        start = !is.null(membership),
        n_iterations = 1,
        membership = membership
      )

      membership <- res$membership
      quality <- res$quality
    }
  }
  res$algorithm <- "leiden"
  res$vcount <- vcount(graph)
  res$membership <- res$membership + 1
  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    res$names <- vertex_attr(graph, "name")
  }
  class(res) <- "communities"
  res
}`

