const rtdal002926Source0049 = "cluster_leading_eigen <- function(\n  graph,\n  steps = -1,\n  weights = NULL,\n  start = NULL,\n  options = arpack_defaults(),\n  callback = NULL,\n  extra = NULL,\n  env = parent.frame()\n) {\n  if (is.function(options)) {\n    lifecycle::deprecate_soft(\n      \"1.6.0\",\n      \"cluster_leading_eigen(options = 'must be a list')\",\n      details = c(\n        \"`arpack_defaults()` is now a function, use `options = arpack_defaults()` instead of `options = arpack_defaults`.\"\n      )\n    )\n    options <- options()\n  }\n\n  # Argument checks\n  ensure_igraph(graph)\n\n  steps <- as.numeric(steps)\n  if (is.null(weights) && \"weight\" %in% edge_attr_names(graph)) {\n    weights <- E(graph)$weight\n  }\n  if (!is.null(weights) && any(!is.na(weights))) {\n    weights <- as.numeric(weights)\n  } else {\n    weights <- NULL\n  }\n\n  # Convert start membership to 0-based indexing and determine start flag\n  start_flag <- !is.null(start)\n  if (start_flag) {\n    start <- as.numeric(start) - 1\n  }\n\n  options <- modify_list(arpack_defaults(), options)\n\n  res <- community_leading_eigenvector_callback_closure_impl(\n    graph = graph,\n    weights = weights,\n    membership = start,\n    steps = steps,\n    options = options,\n    start = start_flag,\n    callback = callback,\n    extra = extra,\n    env = env\n  )\n\n  if (igraph_opt(\"add.vertex.names\") && is_named(graph)) {\n    res$names <- V(graph)$name\n  }\n  res$algorithm <- \"leading eigenvector\"\n  res$vcount <- vcount(graph)\n  res$membership <- res$membership + 1\n  res$merges <- res$merges + 1\n  res$history <- res$history + 1\n  class(res) <- \"communities\"\n  res\n}"

const rtdal002926Source0050 = "cluster_label_prop <- function(\n  graph,\n  weights = NULL,\n  ...,\n  mode = c(\"out\", \"in\", \"all\"),\n  initial = NULL,\n  fixed = NULL\n) {\n  if (...length() > 0) {\n    lifecycle::deprecate_soft(\n      \"1.6.0\",\n      \"cluster_label_prop(... = )\",\n      details = \"Arguments `initial` and `fixed` must be named.\"\n    )\n\n    dots <- list(...)\n    dots[[\"graph\"]] <- graph\n    dots[[\"weights\"]] <- weights\n    if (!is.null(initial)) {\n      dots[[\"initial\"]] <- initial\n    }\n    if (!is.null(fixed)) {\n      dots[[\"fixed\"]] <- fixed\n    }\n\n    return(inject(cluster_label_prop0(!!!dots)))\n  }\n\n  cluster_label_prop0(graph, weights, mode, initial, fixed)\n}"

const rtdal002926Source0051 = `cluster_label_prop0 <- function(
  graph,
  weights = NULL,
  mode = c("out", "in", "all"),
  initial = NULL,
  fixed = NULL
) {
  # Argument checks
  ensure_igraph(graph)

  # Necessary because evaluated later
  mode <- igraph_match_arg(mode)

  # Function call
  membership <- community_label_propagation_impl(
    graph = graph,
    mode = mode,
    weights = weights,
    initial = initial,
    fixed = fixed
  )

  res <- list()
  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    res$names <- V(graph)$name
  }
  res$vcount <- vcount(graph)
  res$algorithm <- "label propagation"
  res$membership <- membership + 1

  res$modularity <- modularity(
    graph,
    res$membership,
    weights,
    directed = (mode != "all")
  )

  class(res) <- "communities"
  res
}`

const rtdal002926Source0052 = `cluster_louvain <- function(graph, weights = NULL, resolution = 1) {
  # Argument checks
  ensure_igraph(graph)

  if (is.null(weights) && "weight" %in% edge_attr_names(graph)) {
    weights <- E(graph)$weight
  }
  if (!is.null(weights) && any(!is.na(weights))) {
    weights <- as.numeric(weights)
  } else {
    weights <- NULL
  }
  resolution <- as.numeric(resolution)

  # Function call
  res <- community_multilevel_impl(
    graph = graph,
    weights = weights,
    resolution = resolution
  )
  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    res$names <- V(graph)$name
  }
  res$vcount <- vcount(graph)
  res$algorithm <- "multi level"
  res$membership <- res$membership + 1
  res$memberships <- res$memberships + 1
  class(res) <- "communities"
  res
}`

