const rtdal002939Source0002 = "fit_power_law <- function(\n  x,\n  xmin = NULL,\n  start = 2,\n  force.continuous = FALSE,\n  implementation = c(\"plfit\", \"R.mle\"),\n  p.value = FALSE,\n  p.precision = NULL,\n  ...\n) {\n  implementation <- igraph_match_arg(implementation)\n\n  if (implementation == \"r.mle\") {\n    if (isTRUE(p.value)) {\n      cli::cli_abort(\n        \"{.arg p.value} is not supported for {.arg implementation} = {.str R.mle}\"\n      )\n    }\n    power.law.fit.old(x, xmin, start, ...)\n  } else if (implementation == \"plfit.p\") {\n    lifecycle::deprecate_stop(\n      \"2.1.0\",\n      'fit_power_law(implementation = \"cannot be \\\\\"plfit.p\\\\\"\")',\n      I('`fit_power_law(implementation = \"plfit\", p.value = TRUE)`')\n    )\n  } else if (implementation == \"plfit\") {\n    xmin <- xmin %||% -1\n    p.precision <- p.precision %||% 0.01\n    power.law.fit.new(\n      x,\n      xmin = xmin,\n      force.continuous = force.continuous,\n      p.value = p.value,\n      p.precision = p.precision\n    )\n  }\n}"

const rtdal002939Source0003 = `power.law.fit.old <- function(x, xmin = NULL, start = 2, ...) {
  if (length(x) < 2) {
    cli::cli_abort(
      "{.arg x} must be a vector of length at least 2, not {length(x)}."
    )
  }

  xmin <- xmin %||% min(x)

  n <- length(x)
  x <- x[x >= xmin]
  if (length(x) != n) {
    n <- length(x)
  }

  #  mlogl <- function(alpha) {
  #    if (xmin > 1) {
  #      C <- 1/(1/(alpha-1)-sum(beta(1:(xmin-1), alpha)))
  #    } else {
  #      C <- alpha-1
  #    }
  #    -n*log(C)-sum(lbeta(x, alpha))
  #  }

  mlogl <- function(alpha) {
    C <- 1 / sum((xmin:10000)^-alpha)
    -n * log(C) + alpha * sum(log(x))
  }

  alpha <- stats4::mle(mlogl, start = list(alpha = start), ...)

  alpha
}`

