const rtdal002940Source0024 = "dominator_tree <- function(graph, root, mode = c(\"out\", \"in\", \"all\", \"total\")) {\n  # Argument checks\n  ensure_igraph(graph)\n\n  if (missing(root) || is.null(root)) {\n    cli::cli_abort(\"{.arg root} must be specified.\")\n  }\n  root <- as_igraph_vs(graph, root)\n\n  mode <- igraph_match_arg(mode)\n\n  # Function call\n  res <- dominator_tree_impl(\n    graph = graph,\n    root = root,\n    mode = mode\n  )\n  if (igraph_opt(\"return.vs.es\")) {\n    res$leftout <- create_vs(graph, res$leftout)\n  }\n\n  # Replace 0 with -1 in `res$dom' to conform with documentation\n  res$dom[res$dom == 0] <- -1\n\n  res\n}"

