const rtdal002941Source0004 = `read.graph.toraw <- function(filename) {
  if (is.character(filename)) {
    filename <- file(filename, open = "rb")
  }
  if (!isOpen(filename)) {
    open(filename, open = "rb")
  }

  tmpbufsize <- 20000
  buffer <- tmpbuffer <- readBin(filename, what = raw(0), n = tmpbufsize)
  while (length(tmpbuffer) == tmpbufsize) {
    tmpbuffer <- readBin(filename, what = raw(0), n = tmpbufsize)
    buffer <- c(buffer, tmpbuffer)
  }
  close(filename)
  rm(tmpbuffer)

  buffer
}`

const rtdal002941Source0006 = `read_graph <- function(
  file,
  format = c(
    "edgelist",
    "pajek",
    "ncol",
    "lgl",
    "graphml",
    "dimacs",
    "graphdb",
    "gml",
    "dl"
  ),
  ...
) {
  if (
    !is.character(file) ||
      length(grep("://", file, fixed = TRUE)) > 0 ||
      length(grep("~", file, fixed = TRUE)) > 0
  ) {
    buffer <- read.graph.toraw(file)
    file <- tempfile()
    write.graph.fromraw(buffer, file)
  }

  format <- igraph_match_arg(format)
  res <- switch(
    format,
    "pajek" = read.graph.pajek(file, ...),
    "ncol" = read.graph.ncol(file, ...),
    "edgelist" = read.graph.edgelist(file, ...),
    "lgl" = read.graph.lgl(file, ...),
    "graphml" = read.graph.graphml(file, ...),
    "dimacs" = read.graph.dimacs(file, ...),
    "graphdb" = read.graph.graphdb(file, ...),
    "gml" = read.graph.gml(file, ...),
    "dl" = read.graph.dl(file, ...)
  )
  res
}`

const rtdal002941Source0007 = `write_graph <- function(
  graph,
  file,
  format = c(
    "edgelist",
    "pajek",
    "ncol",
    "lgl",
    "graphml",
    "dimacs",
    "gml",
    "dot",
    "leda"
  ),
  ...
) {
  ensure_igraph(graph)
  if (
    !is.character(file) ||
      length(grep("://", file, fixed = TRUE)) > 0 ||
      length(grep("~", file, fixed = TRUE)) > 0
  ) {
    tmpfile <- TRUE
    origfile <- file
    file <- tempfile()
  } else {
    tmpfile <- FALSE
  }

  format <- igraph_match_arg(format)
  res <- switch(
    format,
    "pajek" = write.graph.pajek(graph, file, ...),
    "edgelist" = write.graph.edgelist(graph, file, ...),
    "ncol" = write.graph.ncol(graph, file, ...),
    "lgl" = write.graph.lgl(graph, file, ...),
    "graphml" = write.graph.graphml(graph, file, ...),
    "dimacs" = write.graph.dimacs(graph, file, ...),
    "gml" = write.graph.gml(graph, file, ...),
    "dot" = write.graph.dot(graph, file, ...),
    "leda" = write.graph.leda(graph, file, ...)
  )

  if (tmpfile) {
    buffer <- read.graph.toraw(file)
    write.graph.fromraw(buffer, origfile)
  }

  invisible(res)
}`

const rtdal002941Source0016 = `read.graph.dimacs <- function(file, directed = TRUE) {
  res <- .Call(Rx_igraph_read_graph_dimacs, file, as.logical(directed))
  if (res[[1]][1] == "max") {
    graph <- res[[2]]
    graph <- set_graph_attr(graph, "problem", res[[1]])
    graph <- set_graph_attr(graph, "source", res[[3]])
    graph <- set_graph_attr(graph, "target", res[[4]])
    E(graph)$capacity <- res[[5]]
    graph
  } else if (res[[1]][1] == "edge") {
    graph <- res[[2]]
    graph <- set_graph_attr(graph, "problem", res[[1]])
    V(graph)$label <- res[[3]]
    graph
  }
}`

const rtdal002941Source0024 = "graph_from_graphdb <- function(\n  url = NULL,\n  prefix = \"iso\",\n  type = \"r001\",\n  nodes = NULL,\n  pair = \"A\",\n  which = 0,\n  base = \"https://github.com/igraph/graphsdb/raw/refs/heads/main\",\n  compressed = TRUE,\n  directed = TRUE\n) {\n  if (is.null(nodes) && is.null(url)) {\n    cli::cli_abort(\"Either {.arg nodes}' or `{.arg url}' must be non-null.\")\n  }\n\n  if (is.null(url)) {\n    prefixes <- c(\"iso\", \"si6\", \"mcs10\", \"mcs30\", \"mcs50\", \"mcs70\", \"mcs90\")\n    types <- c(\n      \"r001\",\n      \"r005\",\n      \"r01\",\n      \"r02\",\n      \"m2D\",\n      \"m2Dr2\",\n      \"m2Dr4\",\n      \"m2Dr6\",\n      \"m3D\",\n      \"m3Dr2\",\n      \"m3Dr4\",\n      \"m3Dr6\",\n      \"m4D\",\n      \"m4Dr2\",\n      \"m4Dr4\",\n      \"m4Dr6\",\n      \"b03\",\n      \"b03m\",\n      \"b06\",\n      \"b06m\",\n      \"b09\",\n      \"b09m\"\n    )\n    sizecode <- if (nodes <= 100) {\n      \"s\"\n    } else if (nodes < 2000) {\n      \"m\"\n    } else {\n      \"l\"\n    } # \"l\" ????\n    typegroups <- rep(\n      c(\"rand\", \"m2D\", \"m3D\", \"m4D\", \"bvg\"),\n      c(4L, 5L, 3L, 4L, 6L)\n    )\n    typegroup <- typegroups[which(types == type)]\n\n    if (!prefix %in% prefixes) {\n      cli::cli_abort(c(\n        \"{.value {prefix}} is not a valid prefix.\",\n        i = \"Must be one of {.value {prefixes}}.\"\n      ))\n    }\n    if (!type %in% types) {\n      cli::cli_abort(c(\n        \"{.value {type}} is not a valid graph type.\",\n        i = \"Must be one of {.value {types}}.\"\n      ))\n    }\n    suff <- if (compressed) \".gz\" else \"\"\n    filename <- paste(\n      sep = \"\",\n      base,\n      \"/\",\n      prefix,\n      \"/\",\n      typegroup,\n      \"/\",\n      type,\n      \"/\",\n      prefix,\n      \"_\",\n      type,\n      \"_\",\n      sizecode,\n      nodes,\n      \".\",\n      pair,\n      formatC(which, width = 2, flag = \"0\"),\n      suff\n    )\n  } else {\n    filename <- url\n  }\n\n  ## ok, we have the filename\n\n  f <- try(gzcon(file(filename, open = \"rb\")))\n  if (inherits(f, \"try-error\")) {\n    cli::cli_abort(\n      \"Cannot open URL provided in {.arg filename}: {.url {filename}}\"\n    )\n  }\n\n  buffer <- read.graph.toraw(f)\n  f <- tempfile()\n  write.graph.fromraw(buffer, f)\n\n  read_graph_graphdb_impl(\n    instream = f,\n    directed = directed\n  )\n}"

