const rtdal002943Source0001 = `graphlets.project <- function(
  graph,
  weights = NULL,
  cliques,
  niter = 1000,
  Mu = rep(1, length(cliques))
) {
  # nocov start
  lifecycle::deprecate_soft("2.0.0", "graphlets.project()", "graphlet_proj()")
  graphlet_proj(
    graph = graph,
    weights = weights,
    cliques = cliques,
    niter = niter,
    Mu = Mu
  )
}`

