const rtdal002948Source0001 = "obj_type_friendly <- function(x, value = TRUE) {\n  if (is_missing(x)) {\n    return(\"absent\")\n  }\n\n  if (is.object(x)) {\n    if (inherits(x, \"quosure\")) {\n      type <- \"quosure\"\n    } else {\n      type <- class(x)[[1L]]\n    }\n    return(sprintf(\"a <%s> object\", type))\n  }\n\n  if (!is_vector(x)) {\n    return(.rlang_as_friendly_type(typeof(x)))\n  }\n\n  n_dim <- length(dim(x))\n\n  if (!n_dim) {\n    if (!is_list(x) && length(x) == 1) {\n      if (is_na(x)) {\n        return(switch(\n          typeof(x),\n          logical = \"`NA`\",\n          integer = \"an integer `NA`\",\n          double = if (is.nan(x)) {\n            \"`NaN`\"\n          } else {\n            \"a numeric `NA`\"\n          },\n          complex = \"a complex `NA`\",\n          character = \"a character `NA`\",\n          .rlang_stop_unexpected_typeof(x)\n        ))\n      }\n\n      show_infinites <- function(x) {\n        if (x > 0) {\n          \"`Inf`\"\n        } else {\n          \"`-Inf`\"\n        }\n      }\n      str_encode <- function(x, width = 30, ...) {\n        if (nchar(x) > width) {\n          x <- substr(x, 1, width - 3)\n          x <- paste0(x, \"...\")\n        }\n        encodeString(x, ...)\n      }\n\n      if (value) {\n        if (is.numeric(x) && is.infinite(x)) {\n          return(show_infinites(x))\n        }\n\n        if (is.numeric(x) || is.complex(x)) {\n          number <- as.character(round(x, 2))\n          what <- if (is.complex(x)) \"the complex number\" else \"the number\"\n          return(paste(what, number))\n        }\n\n        return(switch(\n          typeof(x),\n          logical = if (x) \"`TRUE`\" else \"`FALSE`\",\n          character = {\n            what <- if (nzchar(x)) \"the string\" else \"the empty string\"\n            paste(what, str_encode(x, quote = \"\\\"\"))\n          },\n          raw = paste(\"the raw value\", as.character(x)),\n          .rlang_stop_unexpected_typeof(x)\n        ))\n      }\n\n      return(switch(\n        typeof(x),\n        logical = \"a logical value\",\n        integer = \"an integer\",\n        double = if (is.infinite(x)) show_infinites(x) else \"a number\",\n        complex = \"a complex number\",\n        character = if (nzchar(x)) \"a string\" else \"\\\"\\\"\",\n        raw = \"a raw value\",\n        .rlang_stop_unexpected_typeof(x)\n      ))\n    }\n\n    if (length(x) == 0) {\n      return(switch(\n        typeof(x),\n        logical = \"an empty logical vector\",\n        integer = \"an empty integer vector\",\n        double = \"an empty numeric vector\",\n        complex = \"an empty complex vector\",\n        character = \"an empty character vector\",\n        raw = \"an empty raw vector\",\n        list = \"an empty list\",\n        .rlang_stop_unexpected_typeof(x)\n      ))\n    }\n  }\n\n  vec_type_friendly(x)\n}"

const rtdal002948Source0002 = "vec_type_friendly <- function(x, length = FALSE) {\n  if (!is_vector(x)) {\n    abort(\"`x` must be a vector.\")\n  }\n  type <- typeof(x)\n  n_dim <- length(dim(x))\n\n  add_length <- function(type) {\n    if (length && !n_dim) {\n      paste0(type, sprintf(\" of length %s\", length(x)))\n    } else {\n      type\n    }\n  }\n\n  if (type == \"list\") {\n    if (n_dim < 2) {\n      return(add_length(\"a list\"))\n    } else if (is.data.frame(x)) {\n      return(\"a data frame\")\n    } else if (n_dim == 2) {\n      return(\"a list matrix\")\n    } else {\n      return(\"a list array\")\n    }\n  }\n\n  type <- switch(\n    type,\n    logical = \"a logical %s\",\n    integer = \"an integer %s\",\n    numeric = ,\n    double = \"a double %s\",\n    complex = \"a complex %s\",\n    character = \"a character %s\",\n    raw = \"a raw %s\",\n    type = paste0(\"a \", type, \" %s\")\n  )\n\n  if (n_dim < 2) {\n    kind <- \"vector\"\n  } else if (n_dim == 2) {\n    kind <- \"matrix\"\n  } else {\n    kind <- \"array\"\n  }\n  out <- sprintf(type, kind)\n\n  if (n_dim >= 2) {\n    out\n  } else {\n    add_length(out)\n  }\n}"

const rtdal002948Source0005 = `obj_type_oo <- function(x) {
  if (!is.object(x)) {
    return("bare")
  }

  class <- inherits(x, c("R6", "S7_object"), which = TRUE)

  if (class[[1]]) {
    "R6"
  } else if (class[[2]]) {
    "S7"
  } else if (isS4(x)) {
    "S4"
  } else {
    "S3"
  }
}`

const rtdal002948Source0006 = "stop_input_type <- function(\n  x,\n  what,\n  ...,\n  allow_na = FALSE,\n  allow_null = FALSE,\n  show_value = TRUE,\n  arg = caller_arg(x),\n  call = caller_env()\n) {\n  # From standalone-cli.R\n  cli <- env_get_list(\n    nms = c(\"format_arg\", \"format_code\"),\n    last = topenv(),\n    default = function(x) sprintf(\"`%s`\", x),\n    inherit = TRUE\n  )\n\n  if (allow_na) {\n    what <- c(what, cli$format_code(\"NA\"))\n  }\n  if (allow_null) {\n    what <- c(what, cli$format_code(\"NULL\"))\n  }\n  if (length(what)) {\n    what <- oxford_comma(what)\n  }\n  if (inherits(arg, \"AsIs\")) {\n    format_arg <- identity\n  } else {\n    format_arg <- cli$format_arg\n  }\n\n  message <- sprintf(\n    \"%s must be %s, not %s.\",\n    format_arg(arg),\n    what,\n    obj_type_friendly(x, value = show_value)\n  )\n\n  abort(message, ..., call = call, arg = arg)\n}"

const rtdal002948Source0007 = `oxford_comma <- function(chr, sep = ", ", final = "or") {
  n <- length(chr)

  if (n < 2) {
    return(chr)
  }

  head <- chr[seq_len(n - 1)]
  last <- chr[n]

  head <- paste(head, collapse = sep)

  # Write a or b. But a, b, or c.
  if (n > 2) {
    paste0(head, sep, final, " ", last)
  } else {
    paste0(head, " ", final, " ", last)
  }
}`

