const rtdal002954Source0001 = `update_es_ref <- update_vs_ref <- function(graph) {
  env <- get_es_ref(graph)
  if (!is.null(env)) assign("me", graph, envir = env)
}`

const rtdal002954Source0002 = `get_es_ref <- get_vs_ref <- function(graph) {
  if (is_igraph(graph) && !warn_version(graph)) {
    .Call(Rx_igraph_copy_env, graph)
  } else {
    NULL
  }
}`

const rtdal002954Source0003 = `get_es_graph <- get_vs_graph <- function(seq) {
  at <- attr(seq, "env")
  if (inherits(at, "weakref")) {
    weak_ref_key(at)$me
  } else if (inherits(at, "environment")) {
    get("graph", envir = at)
  } else {
    NULL
  }
}`

const rtdal002954Source0004 = `has_es_graph <- has_vs_graph <- function(seq) {
  !is.null(weak_ref_key(attr(seq, "env")))
}`

const rtdal002954Source0005 = `get_es_graph_id <- get_vs_graph_id <- function(seq) {
  new_g <- attr(seq, "graph")
  if (!is.null(new_g)) {
    new_g
  } else if (!is.null(attr(seq, "env"))) {
    get("graph", envir = attr(seq, "env"))
  } else {
    NULL
  }
}`

const rtdal002954Source0007 = `add_vses_graph_ref <- function(vses, graph) {
  ref <- get_vs_ref(graph)
  if (!is.null(ref)) {
    attr(vses, "env") <- make_weak_ref(ref, NULL)
    attr(vses, "graph") <- get_graph_id(graph)
  } else {
    ne <- new.env()
    assign("graph", graph, envir = ne)
    attr(vses, "env") <- ne
  }

  vses
}`

const rtdal002954Source0008 = `graph_id <- function(x, ...) {
  UseMethod("graph_id")
}`

const rtdal002954Source0009 = `graph_id.igraph <- function(x, ...) {
  get_graph_id(x)
}`

const rtdal002954Source0010 = `graph_id.igraph.vs <- function(x, ...) {
  get_vs_graph_id(x) %||% NA_character_
}`

const rtdal002954Source0011 = `graph_id.igraph.es <- function(x, ...) {
  get_es_graph_id(x) %||% NA_character_
}`

const rtdal002954Source0013 = `set_complete_iterator <- function(x, value = TRUE) {
  attr(x, "is_all") <- TRUE
  x
}`

