const rtdal002954Source0021 = `V <- function(graph) {
  ensure_igraph(graph)

  update_vs_ref(graph)

  res <- seq_len(vcount(graph))
  if (is_named(graph)) {
    names(res) <- vertex_attr(graph)$name
  }
  class(res) <- "igraph.vs"
  res <- set_complete_iterator(res)
  add_vses_graph_ref(res, graph)
}`

const rtdal002954Source0025 = `E <- function(graph, P = NULL, path = NULL, directed = TRUE) {
  ensure_igraph(graph)

  update_es_ref(graph)

  if (!is.null(P) && !is.null(path)) {
    cli::cli_abort("Cannot use both {.arg P} and {.arg path} at the same time.")
  }

  if (is.null(P) && is.null(path)) {
    ec <- ecount(graph)
    res <- seq_len(ec)
    res <- set_complete_iterator(res)
  } else if (!is.null(P)) {
    on.exit(.Call(Rx_igraph_finalizer))
    res <- .Call(
      Rx_igraph_es_pairs,
      graph,
      as_igraph_vs(graph, P) - 1,
      as.logical(directed)
    ) +
      1
  } else {
    on.exit(.Call(Rx_igraph_finalizer))
    res <- .Call(
      Rx_igraph_es_path,
      graph,
      as_igraph_vs(graph, path) - 1,
      as.logical(directed)
    ) +
      1
  }

  if ("name" %in% edge_attr_names(graph)) {
    names(res) <- edge_attr(graph)$name[res]
  }
  if (is_named(graph)) {
    el <- ends(graph, es = res)
    attr(res, "vnames") <- paste(el[, 1], el[, 2], sep = "|")
  }

  class(res) <- "igraph.es"
  add_vses_graph_ref(res, graph)
}`

const rtdal002954Source0027 = `simple_vs_index <- function(x, i, na_ok = FALSE) {
  res <- unclass(x)[i]
  if (!na_ok && any(is.na(res))) {
    cli::cli_abort("Unknown vertex selected.")
  }
  class(res) <- "igraph.vs"
  res
}`

const rtdal002954Source0028 = "`[.igraph.vs` <- function(x, ..., na_ok = FALSE) {\n  args <- rlang::enquos(..., .ignore_empty = \"all\")\n\n  ## If indexing has no argument at all, then we still get one,\n  ## but it is \"empty\", a name that is  \"\"\n\n  ## Special case, no argument (but we might get an artificial\n  ## empty one\n  if (\n    length(args) < 1 ||\n      (length(args) == 1 &&\n        inherits(rlang::quo_get_expr(args[[1]]), \"name\") &&\n        !nzchar(as.character(rlang::quo_get_expr(args[[1]]))))\n  ) {\n    return(x)\n  }\n\n  ## Special case: single numeric argument\n  first_arg_is_numericish <- inherits(\n    rlang::quo_get_expr(args[[1]]),\n    \"numeric\"\n  ) ||\n    inherits(rlang::quo_get_expr(args[[1]]), \"integer\")\n  if (length(args) == 1 && first_arg_is_numericish) {\n    res <- simple_vs_index(x, rlang::quo_get_expr(args[[1]]), na_ok)\n    return(add_vses_graph_ref(res, get_vs_graph(x)))\n  }\n\n  ## Special case: single symbol argument, no such attribute\n  if (length(args) == 1 && inherits(rlang::quo_get_expr(args[[1]]), \"name\")) {\n    graph <- get_vs_graph(x)\n    if (\n      !(as.character(rlang::quo_get_expr(args[[1]])) %in%\n        vertex_attr_names(graph))\n    ) {\n      res <- simple_vs_index(x, rlang::eval_tidy(args[[1]]), na_ok)\n      return(add_vses_graph_ref(res, graph))\n    }\n  }\n\n  .nei <- function(v, mode = c(\"all\", \"in\", \"out\", \"total\")) {\n    ## TRUE iff the vertex is a neighbor (any type)\n    ## of at least one vertex in v\n    mode <- igraph_match_arg(mode)\n    mode <- switch(mode, \"out\" = 1, \"in\" = 2, \"all\" = 3, \"total\" = 3)\n\n    if (is.logical(v)) {\n      v <- which(v)\n    }\n    on.exit(.Call(Rx_igraph_finalizer))\n    tmp <- .Call(\n      Rx_igraph_vs_nei,\n      graph,\n      x,\n      as_igraph_vs(graph, v) - 1,\n      as.numeric(mode)\n    )\n    tmp[as.numeric(x)]\n  }\n  nei <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"nei()\", \".nei()\")\n  }\n  .innei <- function(v, mode = c(\"in\", \"all\", \"out\", \"total\")) {\n    .nei(v, mode = mode[1])\n  }\n  innei <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"innei()\", \".innei()\")\n  }\n  .outnei <- function(v, mode = c(\"out\", \"all\", \"in\", \"total\")) {\n    .nei(v, mode = mode[1])\n  }\n  outnei <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"outnei()\", \".outnei()\")\n  }\n  .inc <- function(e) {\n    ## TRUE iff the vertex (in the vs) is incident\n    ## to at least one edge in e\n    if (is.logical(e)) {\n      e <- which(e)\n    }\n    on.exit(.Call(Rx_igraph_finalizer))\n    tmp <- .Call(\n      Rx_igraph_vs_adj,\n      graph,\n      x,\n      as_igraph_es(graph, e) - 1,\n      as.numeric(3)\n    )\n    tmp[as.numeric(x)]\n  }\n  inc <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"inc()\", \".inc()\")\n  }\n  adj <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"adj()\", \".inc()\")\n  }\n  .from <- function(e) {\n    ## TRUE iff the vertex is the source of at least one edge in e\n    if (is.logical(e)) {\n      e <- which(e)\n    }\n    on.exit(.Call(Rx_igraph_finalizer))\n    tmp <- .Call(\n      Rx_igraph_vs_adj,\n      graph,\n      x,\n      as_igraph_es(graph, e) - 1,\n      as.numeric(1)\n    )\n    tmp[as.numeric(x)]\n  }\n  from <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"from()\", \".from()\")\n  }\n  .to <- function(e) {\n    ## TRUE iff the vertex is the target of at least one edge in e\n    if (is.logical(e)) {\n      e <- which(e)\n    }\n    on.exit(.Call(Rx_igraph_finalizer))\n    tmp <- .Call(\n      Rx_igraph_vs_adj,\n      graph,\n      x,\n      as_igraph_es(graph, e) - 1,\n      as.numeric(2)\n    )\n    tmp[as.numeric(x)]\n  }\n  to <- function(...) {\n    lifecycle::deprecate_stop(\"2.1.0\", \"to()\", \".to()\")\n  }\n\n  graph <- get_vs_graph(x)\n\n  if (is.null(graph)) {\n    res <- lapply(\n      lapply(args, rlang::eval_tidy),\n      simple_vs_index,\n      x = x,\n      na_ok = na_ok\n    )\n  } else {\n    attrs <- vertex_attr(graph)\n    xvec <- as.vector(x)\n    for (i in seq_along(attrs)) {\n      attrs[[i]] <- attrs[[i]][xvec]\n    }\n\n    env <- parent.frame()\n\n    # Functions (only visible if called or if no duplicate)\n    top <- rlang::new_environment(list(\n      .nei = .nei,\n      nei = nei,\n      .innei = .innei,\n      innei = innei,\n      .outnei = .outnei,\n      outnei = outnei,\n      .inc = .inc,\n      inc = inc,\n      adj = adj,\n      .from = .from,\n      from = from,\n      .to = .to,\n      to = to,\n      .data = list(attrs)\n    ))\n\n    # Data objects (visible by default)\n    bottom <- rlang::new_environment(\n      parent = top,\n      c(\n        attrs,\n        .env = env,\n        .data = list(attrs)\n      )\n    )\n\n    data_mask <- rlang::new_data_mask(bottom, top)\n\n    res <- lapply(args, rlang::eval_tidy, data = data_mask)\n\n    res <- lapply(res, function(ii) {\n      if (is.null(ii)) {\n        return(NULL)\n      }\n      if (is.logical(ii) && (length(ii) != length(x) && length(ii) != 1)) {\n        cli::cli_abort(\n          \"Error: Logical index length does not match the number of vertices. Recycling is not allowed.\"\n        )\n      }\n\n      ii <- simple_vs_index(x, ii, na_ok)\n      attr(ii, \"env\") <- attr(x, \"env\")\n      attr(ii, \"graph\") <- attr(x, \"graph\")\n      class(ii) <- class(x)\n      ii\n    })\n  }\n\n  res <- drop_null(res)\n  if (length(res)) {\n    do_call(c, res)\n  } else {\n    x[FALSE]\n  }\n}"

