const rtdal002954Source0050 = `as_igraph_vs <- function(graph, v, na.ok = FALSE) {
  if (inherits(v, "igraph.vs") && !is.null(graph) && !warn_version(graph)) {
    if (get_graph_id(graph) != get_vs_graph_id(v)) {
      cli::cli_abort("Cannot use a vertex sequence from another graph.")
    }
  }
  if (is.character(v) && "name" %in% vertex_attr_names(graph)) {
    v <- as.numeric(match(v, V(graph)$name))
    if (!na.ok && any(is.na(v))) {
      cli::cli_abort("Invalid vertex names")
    }
    v
  } else {
    if (is.logical(v)) {
      res <- as.vector(V(graph))[v]
    } else if (is.numeric(v) && any(v < 0, na.rm = TRUE)) {
      res <- as.vector(V(graph))[v]
    } else {
      res <- as.numeric(v)
    }
    if (!na.ok && any(is.na(res))) {
      cli::cli_abort("Invalid vertex name(s)")
    }
    res
  }
}`

const rtdal002954Source0051 = `as_igraph_es <- function(graph, e) {
  if (inherits(e, "igraph.es") && !is.null(graph) && !warn_version(graph)) {
    if (get_graph_id(graph) != get_es_graph_id(e)) {
      cli::cli_abort("Cannot use an edge sequence from another graph.")
    }
  }
  if (is.character(e)) {
    Pairs <- grep("|", e, fixed = TRUE)
    Names <- if (length(Pairs) == 0) seq_along(e) else -Pairs
    res <- numeric(length(e))

    ## Based on vertex ids/names
    if (length(Pairs) != 0) {
      vv <- strsplit(e[Pairs], "|", fixed = TRUE)
      vl <- sapply(vv, length)
      if (any(vl != 2)) {
        cli::cli_abort("Invalid edge name: ", e[Pairs][vl != 2][1])
      }
      vp <- unlist(vv)
      if (!"name" %in% vertex_attr_names(graph)) {
        vp <- as.numeric(vp)
      }
      res[Pairs] <- get_edge_ids(graph, vp)
    }

    ## Based on edge ids/names
    if (length(Names) != 0) {
      if ("name" %in% edge_attr_names(graph)) {
        res[Names] <- as.numeric(match(e[Names], E(graph)$name))
      } else {
        res[Names] <- as.numeric(e[Names])
      }
    }
  } else {
    res <- as.numeric(e)
  }
  if (any(is.na(res))) {
    cli::cli_abort("Invalid edge names")
  }
  res
}`

const rtdal002954Source0054 = `parse_op_args <- function(..., what, is_fun, as_fun, check_graph = TRUE) {
  args <- list(...)

  if (any(!sapply(args, is_fun))) {
    cli::cli_abort("Not {what} sequence")
  }

  ## get the ids of all graphs
  graph_id <- sapply(args, get_vs_graph_id) %>%
    unique()

  if (length(graph_id) != 1) {
    cli::cli_warn(c(
      "Combining vertex/edge sequences from different graphs.",
      x = "This will not work in future igraph versions."
    ))
  }

  graphs <- args %>%
    lapply(get_vs_graph) %>%
    drop_null()

  addresses <- graphs %>%
    sapply(function(x) x %&&% address(x)) %>%
    unique()

  if (check_graph && length(addresses) >= 2) {
    cli::cli_warn(
      "Combining vertex/edge sequences from different graphs",
      x = "This will not work in future igraph versions."
    )
  }

  graph <- if (length(graphs)) graphs[[1]]

  args <- lapply(args, unclass)

  list(graph = graph, args = args, id = graph_id)
}`

