const rtdal002956Source0051 = "make_lattice <- function(\n  dimvector = NULL,\n  length = NULL,\n  dim = NULL,\n  nei = 1,\n  directed = FALSE,\n  mutual = FALSE,\n  periodic = FALSE,\n  circular = deprecated()\n) {\n  if (lifecycle::is_present(circular)) {\n    lifecycle::deprecate_soft(\n      \"2.0.3\",\n      \"make_lattice(circular = 'use periodic argument instead')\",\n      details = c(\"`circular` is now deprecated, use `periodic` instead.\")\n    )\n    periodic <- circular\n  }\n\n  if (is.numeric(length) && length != floor(length)) {\n    cli::cli_warn(\"{.arg length} was rounded to the nearest integer.\")\n    length <- round(length)\n  }\n\n  if (is.null(dimvector)) {\n    dimvector <- rep(length, dim)\n  }\n\n  if (length(periodic) == 1) {\n    periodic <- rep(periodic, length(dimvector))\n  }\n\n  res <- square_lattice_impl(\n    dimvector = dimvector,\n    nei = nei,\n    directed = directed,\n    mutual = mutual,\n    periodic = periodic\n  )\n\n  if (igraph_opt(\"add.params\")) {\n    res$name <- \"Lattice graph\"\n    res$dimvector <- dimvector\n    res$nei <- nei\n    res$mutual <- mutual\n    res$circular <- periodic\n  }\n  res\n}"

const rtdal002956Source0055 = `make_wheel <- function(
  n,
  ...,
  mode = c("in", "out", "mutual", "undirected"),
  center = 1
) {
  check_dots_empty()
  res <- wheel_impl(
    n = n,
    mode = mode,
    center = center - 1
  )
  if (igraph_opt("add.params")) {
    res$name <- switch(
      igraph_match_arg(mode),
      "in" = "In-wheel",
      "out" = "Out-wheel",
      "Wheel"
    )
    res$mode <- mode
    res$center <- center
  }
  res
}`

const rtdal002956Source0056 = `wheel <- function(
  n,
  ...,
  mode = c("in", "out", "mutual", "undirected"),
  center = 1
) {
  check_dots_empty()
  constructor_spec(make_wheel, n, mode = mode, center = center)
}`

const rtdal002956Source0059 = `tree <- function(...) {
  constructor_spec(list(make = make_tree, sample = sample_tree), ...)
}`

const rtdal002956Source0074 = `make_full_bipartite_graph <- function(
  n1,
  n2,
  directed = FALSE,
  mode = c("all", "out", "in")
) {
  n1 <- as.numeric(n1)
  n2 <- as.numeric(n2)
  directed <- as.logical(directed)
  mode1 <- switch(
    igraph_match_arg(mode),
    "out" = 1,
    "in" = 2,
    "all" = 3,
    "total" = 3
  )

  res <- full_bipartite_impl(
    n1 = n1,
    n2 = n2,
    directed = directed,
    mode = mode
  )
  if (igraph_opt("add.params")) {
    res$graph$name <- "Full bipartite graph"
    res$n1 <- n1
    res$n2 <- n2
    res$mode <- mode
  }
  set_vertex_attr(res$graph, "type", value = res$types)
}`

const rtdal002956Source0076 = `make_bipartite_graph <- function(types, edges, directed = FALSE) {
  vertex.names <- names(types)

  if (is.character(edges)) {
    if (is.null(vertex.names)) {
      cli::cli_abort(
        "{.arg types} vector must be named when the edge vector contains strings"
      )
    }
    edges <- match(edges, vertex.names)
    if (any(is.na(edges))) {
      cli::cli_abort(
        "edge vector contains a vertex name that is not found in {.arg types}"
      )
    }
  }

  types <- as.logical(types)
  edges <- as.numeric(edges) - 1
  directed <- as.logical(directed)

  res <- create_bipartite_impl(
    types = types,
    edges = edges,
    directed = directed
  )
  res <- set_vertex_attr(res, "type", value = types)

  if (!is.null(vertex.names)) {
    res <- set_vertex_attr(res, "name", value = vertex.names)
  }

  res
}`

const rtdal002956Source0084 = `graph_from_lcf <- function(
  shifts,
  ...,
  n = NULL,
  repeats = 1L
) {
  if (!rlang::is_integer(shifts)) {
    cli::cli_abort(
      "{.arg shift} must be an integer vector, not {.obj_type_friendly {shifts}}."
    )
  }

  check_dots_empty()

  n <- n %||% (length(shifts) * repeats)
  if (!rlang::is_integer(n, n = 1)) {
    cli::cli_abort(
      "{.arg n} must be an integer of length 1, not {.obj_type_friendly {n}}."
    )
  }

  if (!rlang::is_integer(repeats, n = 1)) {
    cli::cli_abort(
      "{.arg repeats} must be an integer of length 1, not {.obj_type_friendly {repeats}}."
    )
  }

  lcf_vector_impl(
    n = n,
    shifts = shifts,
    repeats = repeats
  )
}`

const rtdal002956Source0086 = `realize_bipartite_degseq <- function(
  degrees1,
  degrees2,
  ...,
  allowed.edge.types = c("simple", "multiple"),
  method = c("smallest", "largest", "index")
) {
  check_dots_empty()
  allowed.edge.types <- igraph_match_arg(allowed.edge.types)
  method <- igraph_match_arg(method)
  g <- realize_bipartite_degree_sequence_impl(
    degrees1 = degrees1,
    degrees2 = degrees2,
    allowed_edge_types = allowed.edge.types,
    method = method
  )

  # Add backward-compatible dotted names
  if (igraph_opt("add.params")) {
    g$allowed.edge.types <- g$allowed_edge_types
  }

  V(g)$type <- c(rep(TRUE, length(degrees1)), rep(FALSE, length(degrees2)))
  g
}`

