const rtdal002965Source0019 = `difference.igraph <- function(big, small, byname = "auto", ...) {
  ensure_igraph(big)
  ensure_igraph(small)
  if (byname != "auto" && !is.logical(byname)) {
    cli::cli_abort("{.arg bynam} must be \"auto\", or \"logical\".")
  }
  nonamed <- is_named(big) + is_named(small)
  if (byname == "auto") {
    byname <- nonamed == 2
    if (nonamed == 1) {
      cli::cli_warn(
        "One, but not both graphs are named, not using vertex names."
      )
    }
  } else if (byname && nonamed != 2) {
    cli::cli_abort("Some graphs are not named.")
  }

  if (byname) {
    bnames <- V(big)$name
    snames <- V(small)$name
    if (any(!snames %in% bnames)) {
      small <- small - setdiff(snames, bnames)
      snames <- V(small)$name
    }
    perm <- match(bnames, snames)
    if (any(is.na(perm))) {
      perm[is.na(perm)] <- seq(from = vcount(small) + 1, to = vcount(big))
    }
    big <- permute(big, perm)

    res <- difference_impl(orig = big, sub = small)
    permute(res, match(V(res)$name, bnames))
  } else {
    difference_impl(orig = big, sub = small)
  }
}`

