const rtdal002966Source0004 = `running_mean <- function(v, binwidth) {
  v <- as.numeric(v)
  binwidth <- as.numeric(binwidth)
  if (length(v) < binwidth) {
    cli::cli_abort("Vector too short for this binwidth.")
  }

  running_mean_impl(
    data = v,
    binwidth = binwidth
  )
}`

const rtdal002966Source0005 = `sample_seq <- function(low, high, length) {
  if (length > high - low + 1) {
    cli::cli_abort("length too big for this interval")
  }

  random_sample_impl(low, high, length)
}`

const rtdal002966Source0006 = "handle_vertex_type_arg <- function(types, graph, required = T) {\n  if (is.null(types) && \"type\" %in% vertex_attr_names(graph)) {\n    types <- V(graph)$type\n  }\n  if (!is.null(types)) {\n    if (!is.logical(types)) {\n      cli::cli_warn(\"vertex types converted to logical.\")\n    }\n    types <- as.logical(types)\n    if (any(is.na(types))) {\n      cli::cli_abort(\"`NA' is not allowed in vertex types\")\n    }\n  }\n  if (is.null(types) && required) {\n    cli::cli_abort(\n      \"Not a bipartite graph, supply {.arg types} argument or add a vertex attribute named {.arg type}.\"\n    )\n  }\n  return(types)\n}"

const rtdal002966Source0007 = `igraph.i.spMatrix <- function(M) {
  if (M$type == "triplet") {
    Matrix::sparseMatrix(dims = M$dim, i = M$i + 1L, j = M$p + 1L, x = M$x)
  } else {
    new(
      "dgCMatrix",
      Dim = M$dim,
      Dimnames = list(NULL, NULL),
      factors = list(),
      i = M$i,
      p = M$p,
      x = M$x
    )
  }
}`

