const rtdal002973Source0015 = `.igraph.shape.rectangle.clip <- function(
  coords,
  el,
  params,
  end = c("both", "from", "to")
) {
  end <- match.arg(end)

  if (length(coords) == 0) {
    return(coords)
  }

  vertex.size <- params("vertex", "size")
  vertex.size2 <- params("vertex", "size2")

  rec.shift <- function(x0, y0, x1, y1, vsize, vsize2) {
    m <- (y0 - y1) / (x0 - x1)
    l <- cbind(
      x1 - vsize2 / m,
      y1 - vsize2,
      x1 - vsize,
      y1 - vsize * m,
      x1 + vsize2 / m,
      y1 + vsize2,
      x1 + vsize,
      y1 + vsize * m
    )

    v <- cbind(
      x1 - vsize <= l[, 1] &
        l[, 1] <= x1 + vsize &
        y1 - vsize2 <= l[, 2] &
        l[, 2] <= y1 + vsize2,
      x1 - vsize <= l[, 3] &
        l[, 3] <= x1 + vsize &
        y1 - vsize2 <= l[, 4] &
        l[, 4] <= y1 + vsize2,
      x1 - vsize <= l[, 5] &
        l[, 5] <= x1 + vsize &
        y1 - vsize2 <= l[, 6] &
        l[, 6] <= y1 + vsize2,
      x1 - vsize <= l[, 7] &
        l[, 7] <= x1 + vsize &
        y1 - vsize2 <= l[, 8] &
        l[, 8] <= y1 + vsize2
    )

    d <- cbind(
      (l[, 1] - x0)^2 + (l[, 2] - y0)^2,
      (l[, 3] - x0)^2 + (l[, 4] - y0)^2,
      (l[, 5] - x0)^2 + (l[, 6] - y0)^2,
      (l[, 7] - x0)^2 + (l[, 8] - y0)^2
    )

    t(sapply(seq(length.out = nrow(l)), function(x) {
      d[x, ][!v[x, ]] <- Inf
      m <- which.min(d[x, ])
      l[x, c(m * 2 - 1, m * 2)]
    }))
  }

  if (end %in% c("from", "both")) {
    vsize <- if (length(vertex.size) == 1) {
      vertex.size
    } else {
      vertex.size[el[, 1]]
    }
    vsize2 <- if (length(vertex.size2) == 1) {
      vertex.size2
    } else {
      vertex.size2[el[, 1]]
    }
    res <- res1 <- rec.shift(
      coords[, 3],
      coords[, 4],
      coords[, 1],
      coords[, 2],
      vsize,
      vsize2
    )
  }
  if (end %in% c("to", "both")) {
    vsize <- if (length(vertex.size) == 1) {
      vertex.size
    } else {
      vertex.size[el[, 2]]
    }
    vsize2 <- if (length(vertex.size2) == 1) {
      vertex.size2
    } else {
      vertex.size2[el[, 2]]
    }
    res <- res2 <- rec.shift(
      coords[, 1],
      coords[, 2],
      coords[, 3],
      coords[, 4],
      vsize,
      vsize2
    )
  }
  if (end == "both") {
    res <- cbind(res1, res2)
  }

  res
}`

const rtdal002973Source0016 = `.igraph.shape.rectangle.plot <- function(coords, v = NULL, params) {
  vertex.color <- params("vertex", "color")
  if (length(vertex.color) != 1 && !is.null(v)) {
    vertex.color <- vertex.color[v]
  }
  vertex.frame.color <- params("vertex", "frame.color")
  if (length(vertex.frame.color) != 1 && !is.null(v)) {
    vertex.frame.color <- vertex.frame.color[v]
  }
  vertex.frame.width <- params("vertex", "frame.width")
  if (length(vertex.frame.width) != 1 && !is.null(v)) {
    vertex.frame.width <- vertex.frame.width[v]
  }
  vertex.size <- params("vertex", "size")
  if (length(vertex.size) != 1 && !is.null(v)) {
    vertex.size <- vertex.size[v]
  }
  vertex.size <- rep(vertex.size, length.out = nrow(coords))
  vertex.size2 <- params("vertex", "size2")

  if (length(vertex.size2) != 1 && !is.null(v)) {
    vertex.size2 <- vertex.size2[v]
  }
  vertex.size <- cbind(vertex.size, vertex.size2)

  # Handle vertex.frame.width <= 0 by hiding the border
  vertex.frame.color[vertex.frame.width <= 0] <- NA
  vertex.frame.width[vertex.frame.width <= 0] <- 1

  if (length(vertex.frame.width) == 1) {
    symbols(
      x = coords[, 1],
      y = coords[, 2],
      bg = vertex.color,
      fg = vertex.frame.color,
      rectangles = 2 * vertex.size,
      lwd = vertex.frame.width,
      add = TRUE,
      inches = FALSE
    )
  } else {
    mapply(
      coords[, 1],
      coords[, 2],
      vertex.color,
      vertex.frame.color,
      vertex.size[, 1],
      vertex.size[, 2],
      vertex.frame.width,
      FUN = function(x, y, bg, fg, size, size2, lwd) {
        symbols(
          x = x,
          y = y,
          bg = bg,
          fg = fg,
          lwd = lwd,
          rectangles = 2 * cbind(size, size2),
          add = TRUE,
          inches = FALSE
        )
      }
    )
  }
}`

const rtdal002973Source0017 = `.igraph.shape.crectangle.clip <- function(
  coords,
  el,
  params,
  end = c("both", "from", "to")
) {
  end <- match.arg(end)

  if (length(coords) == 0) {
    return(coords)
  }

  vertex.size <- params("vertex", "size")
  vertex.size2 <- params("vertex", "size2")

  rec.shift <- function(x0, y0, x1, y1, vsize, vsize2) {
    l <- cbind(
      x1,
      y1 - vsize2,
      x1 - vsize,
      y1,
      x1,
      y1 + vsize2,
      x1 + vsize,
      y1
    )

    d <- cbind(
      (l[, 1] - x0)^2 + (l[, 2] - y0)^2,
      (l[, 3] - x0)^2 + (l[, 4] - y0)^2,
      (l[, 5] - x0)^2 + (l[, 6] - y0)^2,
      (l[, 7] - x0)^2 + (l[, 8] - y0)^2
    )

    t(sapply(seq(length.out = nrow(l)), function(x) {
      m <- which.min(d[x, ])
      l[x, c(m * 2 - 1, m * 2)]
    }))
  }

  if (end %in% c("from", "both")) {
    vsize <- if (length(vertex.size) == 1) {
      vertex.size
    } else {
      vertex.size[el[, 1]]
    }
    vsize2 <- if (length(vertex.size2) == 1) {
      vertex.size2
    } else {
      vertex.size2[el[, 1]]
    }
    res <- res1 <- rec.shift(
      coords[, 3],
      coords[, 4],
      coords[, 1],
      coords[, 2],
      vsize,
      vsize2
    )
  }
  if (end %in% c("to", "both")) {
    vsize <- if (length(vertex.size) == 1) {
      vertex.size
    } else {
      vertex.size[el[, 2]]
    }
    vsize2 <- if (length(vertex.size2) == 1) {
      vertex.size2
    } else {
      vertex.size2[el[, 2]]
    }
    res <- res2 <- rec.shift(
      coords[, 1],
      coords[, 2],
      coords[, 3],
      coords[, 4],
      vsize,
      vsize2
    )
  }
  if (end == "both") {
    res <- cbind(res1, res2)
  }

  res
}`

