const rtdal002976Source0006 = `head_print <- function(
  x,
  max_lines = 20,
  header = "",
  footer = "",
  omitted_footer = "",
  ...
) {
  if (is_printer_callback(x)) {
    head_print_callback(x, max_lines, header, footer, omitted_footer, ...)
  } else {
    head_print_object(x, max_lines, header, footer, omitted_footer, ...)
  }
  invisible(x)
}`

const rtdal002976Source0007 = `head_print_object <- function(
  x,
  max_lines,
  header,
  footer,
  omitted_footer,
  print_fun = print,
  ...
) {
  print_header(header)

  cout <- capture.output(print_fun(x, ...))
  cout_no <- min(length(cout), max_lines)
  cat(cout[seq_len(cout_no)], sep = "\n")

  print_footer(footer)

  if (cout_no < length(cout)) {
    print_footer(omitted_footer)
  }

  invisible(c(lines = length(cout), printed = cout_no))
}`

const rtdal002976Source0008 = `head_print_callback <- function(
  x,
  max_lines,
  header,
  footer,
  omitted_footer,
  ...
) {
  ## Header
  print_header(header)

  len <- x("length")
  minw <- x("min_width")
  ow <- getOption("width", 80)

  ## Max number of items we can print. This is an upper bound.
  can_max <- min(floor(ow / minw) * max_lines, len)
  if (can_max == 0) {
    return()
  }

  ## Width of item if we print up to this
  cm <- x("width", no = can_max)

  ## How many rows we need if we print up to a certain point
  no_rows <- ceiling(cm * seq_along(cm) / (ow - 4))

  ## So how many items should we print?
  no <- tail(which(no_rows <= max_lines), 1)
  if (is.null(no) || length(no) < 1 || is.na(no)) {
    no <- can_max
  }

  cat_pern <- function(..., sep = "\n") cat(..., sep = sep)

  ## Format them, and print
  out_lines <- head_print_object(
    x("print", no = no, ...),
    print_fun = cat_pern,
    max_lines = max_lines,
    header = "",
    footer = "",
    omitted_footer = ""
  )

  done_stat <- c(
    tried_items = no,
    tried_lines = out_lines[["lines"]],
    printed_lines = out_lines[["printed"]]
  )

  if (
    done_stat["tried_items"] < len ||
      done_stat["printed_lines"] < done_stat["tried_lines"]
  ) {
    print_footer(omitted_footer)
  }

  x("done", done_stat)

  ## Footer
  print_footer(footer)
}`

const rtdal002976Source0009 = `indent_print <- function(..., .indent = " ", .printer = print) {
  if (length(.indent) != 1 || !is.character(.indent)) {
    indent <- .indent # cli literal cannot start with a dot
    cli::cli_abort(
      "{.arg .indent} must be a character scalar, not {.obj_type_friendly {indent}}."
    )
  }

  opt <- options(width = getOption("width") - nchar(.indent))
  on.exit(options(opt), add = TRUE)

  cout <- capture.output(.printer(...))
  if (length(cout)) {
    cout <- paste0(.indent, cout)
    cat(cout, sep = "\n")
  }

  invisible(list(...)[[1]])
}`

