const rtdal002981Source0001 = `similarity <- function(
  graph,
  vids = V(graph),
  mode = c(
    "all",
    "out",
    "in",
    "total"
  ),
  loops = FALSE,
  method = c(
    "jaccard",
    "dice",
    "invlogweighted"
  )
) {
  method <- igraph_match_arg(method)
  if (method == "jaccard") {
    similarity_jaccard_impl(
      graph = graph,
      vids = vids,
      mode = mode,
      loops = loops
    )
  } else if (method == "dice") {
    similarity_dice_impl(
      graph = graph,
      vids = vids,
      mode = mode,
      loops = loops
    )
  } else if (method == "invlogweighted") {
    similarity_inverse_log_weighted_impl(
      graph = graph,
      vids = vids,
      mode = mode
    )
  }
}`

