const rtdal002984Source0001 = `sdf <- function(..., row.names = NULL, NROW = NULL) {
  cols <- list(...)

  if (
    is.null(names(cols)) ||
      any(names(cols) == "") ||
      any(duplicated(names(cols)))
  ) {
    cli::cli_abort("Columns must be have (unique) names.")
  }

  lens <- sapply(cols, length)
  n1lens <- lens[lens != 1]

  if (length(unique(n1lens)) > 1) {
    cli::cli_abort("Columns must be constants or have the same length.")
  }

  if (length(n1lens) == 0) {
    if (is.null(NROW)) {
      cli::cli_abort("Cannot determine number of rows.")
    }
    attr(cols, "NROW") <- NROW
  } else {
    if (!is.null(NROW) && n1lens[1] != NROW) {
      cli::cli_abort("{.arg NROW} does not match column lengths.")
    }
    attr(cols, "NROW") <- unname(n1lens[1])
  }

  class(cols) <- "igraphSDF"
  attr(cols, "row.names") <- row.names

  cols
}`

const rtdal002984Source0002 = `as.data.frame.igraphSDF <- function(x, row.names, optional, ...) {
  as.data.frame(lapply(x, rep, length.out = attr(x, "NROW")))
}`

const rtdal002984Source0003 = "`[.igraphSDF` <- function(x, i, j, ..., drop = TRUE) {\n  if (!is.character(j)) {\n    cli::cli_abort(\"The column index must be character.\")\n  }\n  if (!missing(i) && !is.numeric(i)) {\n    cli::cli_abort(\"The row index must be numeric.\")\n  }\n  if (missing(i)) {\n    rep(x[[j]], length.out = attr(x, \"NROW\"))\n  } else {\n    if (length(x[[j]]) == 1) {\n      rep(x[[j]], length(i))\n    } else {\n      x[[j]][i]\n    }\n  }\n}"

const rtdal002984Source0004 = "`[<-.igraphSDF` <- function(x, i, j, value) {\n  if (!is.character(j)) {\n    cli::cli_abort(\"The column index must be character.\")\n  }\n  if (!missing(i) && !is.numeric(i)) {\n    cli::cli_abort(\"Row index must be numeric, if given.\")\n  }\n  if (missing(i)) {\n    if (length(value) != attr(x, \"NROW\") && length(value) != 1) {\n      cli::cli_abort(\"Replacement value has the wrong length.\")\n    }\n    x[[j]] <- value\n  } else {\n    if (length(value) != length(i) && length(value) != 1) {\n      cli::cli_abort(\"Replacement value has the wrong length.\")\n    }\n    tmp <- rep(x[[j]], length.out = attr(x, \"NROW\"))\n    tmp[i] <- value\n    if (length(unique(tmp)) == 1) {\n      tmp <- tmp[1]\n    }\n    x[[j]] <- tmp\n  }\n\n  x\n}"

