const rtdal002986Source0033 = `degree <- function(
  graph,
  v = V(graph),
  mode = c("all", "out", "in", "total"),
  loops = TRUE,
  normalized = FALSE
) {
  ensure_igraph(graph)
  v <- as_igraph_vs(graph, v)
  mode <- igraph_match_arg(mode)

  res <- degree_impl(
    graph = graph,
    vids = v,
    mode = mode,
    loops = loops
  )

  if (normalized) {
    res <- res / (vcount(graph) - 1)
  }
  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    names(res) <- V(graph)$name[v]
  }
  res
}`

