const rtdal002986Source0046 = `transitivity <- function(
  graph,
  type = c(
    "undirected",
    "global",
    "globalundirected",
    "localundirected",
    "local",
    "average",
    "localaverage",
    "localaverageundirected",
    "barrat",
    "weighted"
  ),
  vids = NULL,
  weights = NULL,
  isolates = c("NaN", "zero")
) {
  ensure_igraph(graph)
  type <- igraph_match_arg(type)
  type <- switch(
    type,
    "undirected" = 0L,
    "global" = 0L,
    "globalundirected" = 0L,
    "localundirected" = 1L,
    "local" = 1L,
    "average" = 2L,
    "localaverage" = 2L,
    "localaverageundirected" = 2L,
    "barrat" = 3L,
    "weighted" = 3L
  )

  if (is.null(weights) && "weight" %in% edge_attr_names(graph)) {
    weights <- E(graph)$weight
  }
  if (!is.null(weights) && any(!is.na(weights))) {
    weights <- as.numeric(weights)
  } else {
    weights <- NULL
  }

  isolates <- igraph_match_arg(isolates)

  if (type == 0) {
    transitivity_undirected_impl(
      graph = graph,
      mode = isolates
    )
  } else if (type == 1) {
    isolates_num <- as.double(switch(isolates, "nan" = 0, "zero" = 1))
    if (is.null(vids)) {
      res <- .Call(
        Rx_igraph_transitivity_local_undirected_all,
        graph,
        isolates_num
      )
      if (igraph_opt("add.vertex.names") && is_named(graph)) {
        names(res) <- V(graph)$name
      }
      res
    } else {
      res <- transitivity_local_undirected_impl(
        graph = graph,
        vids = vids,
        mode = isolates
      )
      if (igraph_opt("add.vertex.names") && is_named(graph)) {
        vids_indices <- as_igraph_vs(graph, vids)
        names(res) <- V(graph)$name[vids_indices]
      }
      res
    }
  } else if (type == 2) {
    transitivity_avglocal_undirected_impl(
      graph = graph,
      mode = isolates
    )
  } else if (type == 3) {
    # Save original vids for naming if needed
    vids_for_names <- if (is.null(vids)) V(graph) else vids

    res <- if (is.null(weights)) {
      if (is.null(vids)) {
        transitivity_local_undirected_impl(
          graph = graph,
          mode = isolates
        )
      } else {
        transitivity_local_undirected_impl(
          graph = graph,
          vids = vids,
          mode = isolates
        )
      }
    } else {
      if (is.null(vids)) {
        transitivity_barrat_impl(
          graph = graph,
          weights = weights,
          mode = isolates
        )
      } else {
        transitivity_barrat_impl(
          graph = graph,
          vids = vids,
          weights = weights,
          mode = isolates
        )
      }
    }

    if (igraph_opt("add.vertex.names") && is_named(graph)) {
      vids_indices <- as_igraph_vs(graph, vids_for_names)
      names(res) <- V(graph)$name[vids_indices]
    }
    res
  }
}`

