const rtdal002986Source0060 = `girth <- function(graph, circle = TRUE) {
  ensure_igraph(graph)

  on.exit(.Call(Rx_igraph_finalizer))
  res <- .Call(Rx_igraph_girth, graph, as.logical(circle))
  if (res$girth == 0) {
    res$girth <- Inf
  }
  if (igraph_opt("return.vs.es") && circle) {
    res$circle <- create_vs(graph, res$circle)
  }
  res
}`

const rtdal002986Source0067 = `bfs <- function(
  graph,
  root,
  mode = c("out", "in", "all", "total"),
  ...,
  unreachable = TRUE,
  restricted = NULL,
  order = TRUE,
  rank = FALSE,
  parent = FALSE,
  pred = FALSE,
  succ = FALSE,
  dist = FALSE,
  callback = NULL,
  extra = NULL,
  rho = parent.frame(),
  neimode = deprecated(),
  father = deprecated()
) {
  rlang::check_dots_empty()

  ensure_igraph(graph)

  if (lifecycle::is_present(neimode)) {
    lifecycle::deprecate_stop(
      "1.3.0",
      "bfs(neimode = )",
      "bfs(mode = )"
    )
  }

  if (lifecycle::is_present(father)) {
    lifecycle::deprecate_warn("2.2.0", "bfs(father = )", "bfs(parent = )")
    if (missing(parent)) {
      parent <- father
    }
  }

  if (length(root) == 1) {
    root <- as_igraph_vs(graph, root) - 1
    roots <- NULL
  } else {
    roots <- as_igraph_vs(graph, root) - 1
    root <- 0 # ignored anyway
  }
  mode <- switch(
    igraph_match_arg(mode),
    "out" = 1,
    "in" = 2,
    "all" = 3,
    "total" = 3
  )
  unreachable <- as.logical(unreachable)
  if (!is.null(restricted)) {
    restricted <- as_igraph_vs(graph, restricted) - 1
  }
  if (!is.null(callback)) {
    callback <- as.function(callback)
  }

  on.exit(.Call(Rx_igraph_finalizer))
  res <- .Call(
    Rx_igraph_bfs,
    graph,
    root,
    roots,
    mode,
    unreachable,
    restricted,
    as.logical(order),
    as.logical(rank),
    as.logical(parent),
    as.logical(pred),
    as.logical(succ),
    as.logical(dist),
    callback,
    extra,
    rho
  )

  # Remove in 1.4.0
  res$neimode <- res$mode

  if (order) {
    res$order <- res$order + 1
  }
  if (rank) {
    res$rank <- res$rank + 1
  }
  if (parent) {
    res$parent <- res$parent + 1
  }
  if (pred) {
    res$pred <- res$pred + 1
  }
  if (succ) {
    res$succ <- res$succ + 1
  }

  if (igraph_opt("return.vs.es")) {
    if (order) {
      res$order <- V(graph)[.env$res$order, na_ok = TRUE]
    }
    if (parent) {
      res$parent <- create_vs(graph, res$parent, na_ok = TRUE)
    }
    if (pred) {
      res$pred <- create_vs(graph, res$pred, na_ok = TRUE)
    }
    if (succ) res$succ <- create_vs(graph, res$succ, na_ok = TRUE)
  } else {
    if (order) res$order <- res$order[res$order != 0]
  }

  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    if (rank) {
      names(res$rank) <- V(graph)$name
    }
    if (parent) {
      names(res$parent) <- V(graph)$name
    }
    if (pred) {
      names(res$pred) <- V(graph)$name
    }
    if (succ) {
      names(res$succ) <- V(graph)$name
    }
    if (dist) names(res$dist) <- V(graph)$name
  }

  if (rank) {
    res$rank[is.nan(res$rank)] <- 0
  }

  if (dist) {
    res$dist[is.nan(res$dist)] <- -3
  }

  # Remove this later? https://github.com/igraph/rigraph/issues/1576
  res$father <- res$parent

  res
}`

const rtdal002986Source0068 = `dfs <- function(
  graph,
  root,
  mode = c("out", "in", "all", "total"),
  ...,
  unreachable = TRUE,
  order = TRUE,
  order.out = FALSE,
  parent = FALSE,
  dist = FALSE,
  in.callback = NULL,
  out.callback = NULL,
  extra = NULL,
  rho = parent.frame(),
  neimode = deprecated(),
  father = deprecated()
) {
  rlang::check_dots_empty()

  ensure_igraph(graph)
  if (lifecycle::is_present(neimode)) {
    lifecycle::deprecate_stop(
      "1.3.0",
      "dfs(neimode = )",
      "dfs(mode = )"
    )
  }

  if (lifecycle::is_present(father)) {
    lifecycle::deprecate_warn("2.2.0", "dfs(father = )", "dfs(parent = )")
    if (missing(parent)) {
      parent <- father
    }
  }

  root <- as_igraph_vs(graph, root) - 1
  mode <- switch(
    igraph_match_arg(mode),
    "out" = 1,
    "in" = 2,
    "all" = 3,
    "total" = 3
  )
  unreachable <- as.logical(unreachable)
  if (!is.null(in.callback)) {
    in.callback <- as.function(in.callback)
  }
  if (!is.null(out.callback)) {
    out.callback <- as.function(out.callback)
  }

  on.exit(.Call(Rx_igraph_finalizer))
  res <- .Call(
    Rx_igraph_dfs,
    graph,
    root,
    mode,
    unreachable,
    as.logical(order),
    as.logical(order.out),
    as.logical(parent),
    as.logical(dist),
    in.callback,
    out.callback,
    extra,
    rho
  )

  # Remove in 1.4.0
  res$neimode <- res$mode

  if (order) {
    res$order <- res$order + 1
  }
  if (order.out) {
    res$order.out <- res$order.out + 1
  }
  if (parent) {
    res$parent <- res$parent + 1
  }

  if (igraph_opt("return.vs.es")) {
    if (order) {
      res$order <- V(graph)[.env$res$order, na_ok = TRUE]
    }
    if (order.out) {
      res$order.out <- V(graph)[.env$res$order.out, na_ok = TRUE]
    }
    if (parent) res$parent <- create_vs(graph, res$parent, na_ok = TRUE)
  } else {
    if (order) {
      res$order <- res$order[res$order != 0]
    }
    if (order.out) res$order.out <- res$order.out[res$order.out != 0]
  }

  if (igraph_opt("add.vertex.names") && is_named(graph)) {
    if (parent) {
      names(res$parent) <- V(graph)$name
    }
    if (dist) names(res$dist) <- V(graph)$name
  }

  # Remove this later? https://github.com/igraph/rigraph/issues/1576
  res$father <- res$parent

  res
}`

