const rtdal002990Source0009 = `graph.subisomorphic.lad <- function(
  pattern,
  target,
  domains = NULL,
  induced = FALSE,
  map = TRUE,
  all.maps = FALSE,
  time.limit = Inf
) {
  # Argument checks
  ensure_igraph(pattern)
  ensure_igraph(target)
  induced <- as.logical(induced)
  if (time.limit == Inf) {
    time.limit <- 0
  } else {
    time.limit <- as.numeric(time.limit)
  }
  map <- as.logical(map)
  all.maps <- as.logical(all.maps)
  if (!is.null(domains)) {
    if (!is.list(domains)) {
      cli::cli_abort(
        "{.arg domains} must be a list of vertex vectors from {.arg target}."
      )
    }
    if (length(domains) != vcount(pattern)) {
      cli::cli_abort(
        "{.arg domains} length and {.arg pattern} number of vertices must match."
      )
    }
    domains <- lapply(domains, function(x) as_igraph_vs(target, x) - 1)
  }

  on.exit(.Call(Rx_igraph_finalizer))
  # Function call
  res <- .Call(
    Rx_igraph_subisomorphic_lad,
    pattern,
    target,
    domains,
    induced,
    time.limit,
    map,
    all.maps
  )

  if (map) {
    res$map <- res$map + 1
    if (igraph_opt("add.vertex.names") && is_named(target)) {
      names(res$map) <- V(target)$name[res$map]
    }
  }
  if (all.maps) {
    res$maps <- lapply(res$maps, function(.x) V(target)[.x + 1])
  }

  res
}`

const rtdal002990Source0010 = `isomorphic <- function(
  graph1,
  graph2,
  method = c(
    "auto",
    "direct",
    "vf2",
    "bliss"
  ),
  ...
) {
  ensure_igraph(graph1)
  ensure_igraph(graph2)
  method <- igraph_match_arg(method)

  if (method == "auto") {
    isomorphic_impl(
      graph1 = graph1,
      graph2 = graph2
    )
  } else if (method == "direct") {
    isomorphic_impl(
      graph1 = graph1,
      graph2 = graph2
    )
  } else if (method == "vf2") {
    graph.isomorphic.vf2(graph1, graph2, ...)$iso
  } else if (method == "bliss") {
    graph.isomorphic.bliss(graph1, graph2, ...)$iso
  }
}`

const rtdal002990Source0011 = `graph.isomorphic.bliss <- function(
  graph1,
  graph2,
  colors1 = NULL,
  colors2 = NULL,
  sh = c("fm", "f", "fs", "fl", "flm", "fsm")
) {
  isomorphic_bliss_impl(
    graph1 = graph1,
    graph2 = graph2,
    colors1 = if (missing(colors1)) missing_arg() else colors1,
    colors2 = if (missing(colors2)) missing_arg() else colors2,
    sh = sh
  )
}`

