const rtdal002995Source0001 = `make_call <- function(f, ..., .args = list()) {
  if (is.character(f)) {
    f <- as.name(f)
  }
  as.call(c(f, ..., .args))
}`

const rtdal002995Source0002 = `do_call <- function(f, ..., .args = list(), .env = parent.frame()) {
  f <- substitute(f)

  call <- make_call(f, ..., .args)
  eval(call, .env)
}`

const rtdal002995Source0003 = `add_class <- function(x, class) {
  if (!inherits(x, class)) {
    class(x) <- c(class(x), class)
  }
  x
}`

const rtdal002995Source0004 = "`%&&%` <- function(lhs, rhs) {\n  lres <- withVisible(eval(lhs, envir = parent.frame()))\n  if (!is.null(lres$value)) {\n    eval(rhs, envir = parent.frame())\n  } else {\n    if (lres$visible) {\n      lres$value\n    } else {\n      invisible(lres$value)\n    }\n  }\n}"

const rtdal002995Source0006 = `capitalize <- function(x) {
  x <- tolower(x)
  substr(x, 1, 1) <- toupper(substr(x, 1, 1))
  x
}`

const rtdal002995Source0011 = `modify_list <- function(x, y) {
  if (is.null(y)) {
    return(x)
  }

  utils::modifyList(x, y)
}`

