const rtdal003001Source0005 = `make_scan_graphs <- function(version = 1) {
  local_rng_version("3.5.0")
  if (version == 1) {
    withr::local_seed(12345)
    n <- 10^3
    p <- 0.1
    g <- sample_gnp(n, p)
    E(g)$weight <- sample(ecount(g))
    gp <- sample_gnp(n, p)
    E(gp)$weight <- sample(ecount(gp))

    list(g = g, gp = gp)
  } else if (version == 2) {
    withr::local_seed(42)
    n <- 10^3
    p <- 0.1
    g <- sample_gnp(n, p, directed = TRUE)
    E(g)$weight <- sample(ecount(g))
    gp <- sample_gnp(n, p)
    E(gp)$weight <- sample(ecount(gp))
    list(g = g, gp = gp)
  }
}`

