const rtdal003004Source0697 = `test_that("bfs_closure_impl works", {
  withr::local_seed(20250125)
  local_igraph_options(print.id = FALSE)

  g <- make_ring(10)

  # Collect BFS visit data
  bfs_visits <- list()
  result <- bfs_closure_impl(
    graph = g,
    root = 1,
    mode = "out",
    unreachable = TRUE,
    restricted = NULL,
    callback = function(args) {
      bfs_visits[[length(bfs_visits) + 1]] <<- args
      FALSE # Continue
    }
  )

  expect_snapshot({
    cat("BFS result:\n")
    print(result)
    cat("\nNumber of BFS visits:", length(bfs_visits), "\n")
    if (length(bfs_visits) > 0) {
      cat("First visit:\n")
      print(bfs_visits[[1]])
    }
  })

  # Test error handling
  expect_snapshot_igraph_error({
    bfs_closure_impl(
      graph = g,
      root = 1,
      mode = "out",
      unreachable = TRUE,
      restricted = NULL,
      callback = function(args) {
        NA
      }
    )
  })

  expect_snapshot_igraph_error({
    bfs_closure_impl(
      graph = g,
      root = 1,
      mode = "out",
      unreachable = TRUE,
      restricted = NULL,
      callback = function(args) {
        NA
      }
    )
  })

  calls <- 0
  bfs_closure_impl(
    graph = g,
    root = 1,
    mode = "out",
    unreachable = TRUE,
    restricted = NULL,
    callback = function(args) {
      calls <<- calls + 1
      calls > 3 # Stop after 3 calls
    }
  )
  expect_equal(calls, 4) # Called 4 times: 3 continue (FALSE), 1 stop (TRUE)
})`

