const rtdal003009Source0001 = `test_that("subgraph_centrality() works", {
  frucht_graph <- make_graph("Frucht")
  expect_equal(
    subgraph_centrality(frucht_graph),
    Matrix::diag(Matrix::expm(as_adjacency_matrix(
      frucht_graph,
      sparse = FALSE
    ))),
    tolerance = 1e-10
  )

  grotzsch_graph <- make_graph("Grotzsch")
  expect_equal(
    subgraph_centrality(grotzsch_graph),
    Matrix::diag(Matrix::expm(as_adjacency_matrix(
      grotzsch_graph,
      sparse = FALSE
    ))),
    tolerance = 1e-10
  )
})`

const rtdal003009Source0002 = `test_that("subgraph_centrality() ignored edge directions", {
  withr::local_seed(137)
  g <- sample_gnm(10, 20, directed = TRUE)
  expect_equal(
    subgraph_centrality((g)),
    subgraph_centrality(as_undirected(g, mode = "each"))
  )
})`

const rtdal003009Source0003 = "test_that(\"`authority_score()` works\", {\n  rlang::local_options(lifecycle_verbosity = \"quiet\")\n  mscale <- function(x) {\n    if (sd(x) != 0) {\n      x <- scale(x)\n    }\n    if (x[1] < 0) {\n      x <- -x\n    }\n    x\n  }\n\n  g1 <- make_graph(\n    c(\n      1, 3, 1, 6, 1, 10, 2, 1, 3, 1, 4, 2, 4, 7, 4, 9, 5, 4, 5, 6, 5, 8, 6, 3,\n      7, 1, 7, 5, 7, 6, 7, 10, 8, 4, 9, 6, 10, 5, 10, 7\n    ),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g1, sparse = FALSE)\n  s1 <- eigen(t(A) %*% A)$vectors[, 1]\n  s2 <- authority_score(g1)$vector\n  expect_equal(\n    s2,\n    c(\n      0.519632767970952, 0.0191587307007462, 0.327572049088003,\n      0.238728053455971, 0.449690304629051, 1, 0.0966933781044594,\n      0.204851318050036, 0.0191587307007462, 0.653243552177761\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  g2 <- make_graph(\n    c(1, 2, 1, 4, 2, 3, 2, 4, 3, 1, 3, 5, 4, 3, 5, 1, 5, 2),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g2, sparse = FALSE)\n  s1 <- eigen(t(A) %*% A)$vectors[, 1]\n  s2 <- authority_score(g2)$vector\n  expect_equal(\n    s2,\n    c(\n      0.763521118433368, 1, 0.546200349457202,\n      0.918985947228995, 0.28462967654657\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  rlang::with_options(lifecycle_verbosity = \"warning\", {\n    expect_snapshot(\n      s3 <- authority_score(g2, options = arpack_defaults)$vector\n    )\n  })\n  expect_equal(s2, s3)\n})"

const rtdal003009Source0004 = "test_that(\"`hub_score()` works\", {\n  rlang::local_options(lifecycle_verbosity = \"quiet\")\n  mscale <- function(x) {\n    if (sd(x) != 0) {\n      x <- scale(x)\n    }\n    if (x[1] < 0) {\n      x <- -x\n    }\n    x\n  }\n\n  g1 <- make_graph(\n    c(\n      1, 3, 1, 6, 1, 10, 2, 1, 3, 1, 4, 2, 4, 7, 4, 9, 5, 4, 5, 6, 5, 8, 6, 3,\n      7, 1, 7, 5, 7, 6, 7, 10, 8, 4, 9, 6, 10, 5, 10, 7\n    ),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g1, sparse = FALSE)\n  s1 <- eigen(A %*% t(A))$vectors[, 1]\n  s2 <- hub_score(g1)$vector\n  expect_equal(\n    s2,\n    c(\n      0.755296579522977, 0.198139015063149, 0.198139015063149,\n      0.0514804231207635, 0.550445261472941, 0.124905139108053,\n      1, 0.0910284037021176, 0.381305851509012, 0.208339295395331\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  g2 <- make_graph(\n    c(1, 2, 1, 4, 2, 3, 2, 4, 3, 1, 3, 5, 4, 3, 5, 1, 5, 2),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g2, sparse = FALSE)\n  s1 <- eigen(A %*% t(A))$vectors[, 1]\n  s2 <- hub_score(g2)$vector\n  expect_equal(\n    s2,\n    c(\n      1, 0.763521118433368, 0.546200349457203,\n      0.28462967654657, 0.918985947228995\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  rlang::with_options(lifecycle_verbosity = \"warning\", {\n    expect_snapshot(\n      s3 <- hub_score(g2, options = arpack_defaults)$vector\n    )\n  })\n  expect_equal(s2, s3)\n})"

const rtdal003009Source0005 = `test_that("authority_score survives stress test", {
  skip_on_cran()

  withr::local_seed(42)

  expect_principal <- function(M, lambda) {
    expect_equal(eigen(M)$values[1], lambda)
  }

  expect_ev <- function(M, v, lambda) {
    expect_equal(as.vector(M %*% v), lambda * v)
  }

  expect_good <- function(M, v, lambda) {
    expect_principal(M, lambda)
    expect_ev(M, v, lambda)
  }

  for (i in 1:100) {
    repeat {
      G <- sample_gnm(10, sample(15:25, 1), directed = FALSE)
      if (is_connected(G)) break
    }
    G <- as_directed(G, mode = "mutual")
    hs <- hits_scores(G)
    M <- as_adjacency_matrix(G, sparse = FALSE)
    expect_good(M %*% t(M), hs$hub, hs$value)
  }
})`

const rtdal003009Source0006 = "test_that(\"`hits_score()` works -- authority\", {\n  mscale <- function(x) {\n    if (sd(x) != 0) {\n      x <- scale(x)\n    }\n    if (x[1] < 0) {\n      x <- -x\n    }\n    x\n  }\n\n  g1 <- make_graph(\n    c(\n      1, 3, 1, 6, 1, 10, 2, 1, 3, 1, 4, 2, 4, 7, 4, 9, 5, 4, 5, 6, 5, 8, 6, 3,\n      7, 1, 7, 5, 7, 6, 7, 10, 8, 4, 9, 6, 10, 5, 10, 7\n    ),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g1, sparse = FALSE)\n  s1 <- eigen(t(A) %*% A)$vectors[, 1]\n  s2 <- hits_scores(g1)$authority\n  expect_equal(\n    s2,\n    c(\n      0.519632767970952, 0.0191587307007462, 0.327572049088003,\n      0.238728053455971, 0.449690304629051, 1, 0.0966933781044594,\n      0.204851318050036, 0.0191587307007462, 0.653243552177761\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  g2 <- make_graph(\n    c(1, 2, 1, 4, 2, 3, 2, 4, 3, 1, 3, 5, 4, 3, 5, 1, 5, 2),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g2, sparse = FALSE)\n  s1 <- eigen(t(A) %*% A)$vectors[, 1]\n  s2 <- hits_scores(g2)$authority\n  expect_equal(\n    s2,\n    c(\n      0.763521118433368, 1, 0.546200349457202,\n      0.918985947228995, 0.28462967654657\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n})"

const rtdal003009Source0007 = "test_that(\"`hits_scores()` works -- hub\", {\n  mscale <- function(x) {\n    if (sd(x) != 0) {\n      x <- scale(x)\n    }\n    if (x[1] < 0) {\n      x <- -x\n    }\n    x\n  }\n\n  g1 <- make_graph(\n    c(\n      1, 3, 1, 6, 1, 10, 2, 1, 3, 1, 4, 2, 4, 7, 4, 9, 5, 4, 5, 6, 5, 8, 6, 3,\n      7, 1, 7, 5, 7, 6, 7, 10, 8, 4, 9, 6, 10, 5, 10, 7\n    ),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g1, sparse = FALSE)\n  s1 <- eigen(A %*% t(A))$vectors[, 1]\n  s2 <- hits_scores(g1)$hub\n  expect_equal(\n    s2,\n    c(\n      0.755296579522977, 0.198139015063149, 0.198139015063149,\n      0.0514804231207635, 0.550445261472941, 0.124905139108053,\n      1, 0.0910284037021176, 0.381305851509012, 0.208339295395331\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n\n  g2 <- make_graph(\n    c(1, 2, 1, 4, 2, 3, 2, 4, 3, 1, 3, 5, 4, 3, 5, 1, 5, 2),\n    directed = TRUE\n  )\n  A <- as_adjacency_matrix(g2, sparse = FALSE)\n  s1 <- eigen(A %*% t(A))$vectors[, 1]\n  s2 <- hits_scores(g2)$hub\n  expect_equal(\n    s2,\n    c(\n      1, 0.763521118433368, 0.546200349457203,\n      0.28462967654657, 0.918985947228995\n    )\n  )\n  expect_equal(mscale(s1), mscale(s2), ignore_attr = TRUE)\n})"

const rtdal003009Source0008 = `test_that("betweenness() works for kite graph", {
  kite <- graph_from_literal(
    Andre - Beverly:Carol:Diane:Fernando,
    Beverly - Andre:Diane:Ed:Garth,
    Carol - Andre:Diane:Fernando,
    Diane - Andre:Beverly:Carol:Ed:Fernando:Garth,
    Ed - Beverly:Diane:Garth,
    Fernando - Andre:Carol:Diane:Garth:Heather,
    Garth - Beverly:Diane:Ed:Fernando:Heather,
    Heather - Fernando:Garth:Ike,
    Ike - Heather:Jane,
    Jane - Ike
  )
  nf <- (vcount(kite) - 1) * (vcount(kite) - 2) / 2
  bet <- structure(betweenness(kite) / nf, names = V(kite)$name)
  bet <- round(sort(bet, decreasing = TRUE), 3)
  expect_equal(
    bet,
    structure(
      c(0.389, 0.231, 0.231, 0.222, 0.102, 0.023, 0.023, 0.000, 0.000, 0.000),
      names = c("Heather", "Fernando", "Garth", "Ike", "Diane", "Andre", "Beverly", "Carol", "Ed", "Jane")
    )
  )

  bet2 <- structure(betweenness(kite, normalized = TRUE), names = V(kite)$name)
  bet2 <- round(sort(bet2, decreasing = TRUE), 3)
  expect_equal(bet2, bet)
})`

