const rtdal003027Source0034 = `test_that("HSBM with list arguments works", {
  blocks <- 5
  C <- matrix(c(
    1, 1 / 2, 0,
    1 / 2, 0, 1 / 2,
    0, 1 / 2, 1 / 2
  ), nrow = 3)
  vertices_per_block <- 10
  rho <- c(3, 3, 4) / 10

  withr::local_seed(42)
  g_hsbm1 <- sample_hierarchical_sbm(
    blocks * vertices_per_block,
    vertices_per_block,
    rho = rho,
    C = C,
    p = 0
  )

  withr::local_seed(42)
  g_hsbm2 <- sample_hierarchical_sbm(
    blocks * vertices_per_block,
    rep(vertices_per_block, blocks),
    rho = rho,
    C = C,
    p = 0
  )
  expect_equal(g_hsbm1[], g_hsbm2[])

  withr::local_seed(42)
  g_hsbm3 <- sample_hierarchical_sbm(
    blocks * vertices_per_block,
    vertices_per_block,
    rho = replicate(blocks, rho, simplify = FALSE),
    C = C,
    p = 0
  )
  expect_equal(g_hsbm1[], g_hsbm3[])

  withr::local_seed(42)
  g_hsbm4 <- sample_hierarchical_sbm(
    blocks * vertices_per_block,
    vertices_per_block,
    rho = rho,
    C = replicate(blocks, C, simplify = FALSE),
    p = 0
  )

  expect_equal(g_hsbm1[], g_hsbm4[])

  expect_error(
    sample_hierarchical_sbm(
      blocks * vertices_per_block,
      rep(vertices_per_block, blocks),
      rho = list(rho, rho),
      C = C,
      p = 0
    )
  )

  ###

  n <- function(x) x / sum(x)

  rho1 <- n(c(1, 2))
  C1 <- matrix(0, nrow = 2, ncol = 2)
  rho2 <- n(c(3, 3, 4))
  C2 <- matrix(0, nrow = 3, ncol = 3)
  rho3 <- 1
  C3 <- matrix(0)
  rho4 <- n(c(2, 1))
  C4 <- matrix(0, nrow = 2, ncol = 2)

  g_hsbm5 <- sample_hierarchical_sbm(
    21,
    m = c(3, 10, 5, 3),
    rho = list(rho1, rho2, rho3, rho4),
    C = list(C1, C2, C3, C4),
    p = 1
  )
  expect_true(is_simple(g_hsbm5))

  withr::local_seed(42)
  g_hsbm6 <- sample_hierarchical_sbm(
    21,
    m = c(3, 10, 5, 3),
    rho = list(rho1, rho2, rho3, rho4),
    C = list(C1, C2, C3, C4),
    p = 1 - 1e-10
  )
  expect_equal(g_hsbm5[], g_hsbm6[])

  rho1 <- n(c(1, 2))
  C1 <- matrix(1, nrow = 2, ncol = 2)
  rho2 <- n(c(3, 3, 4))
  C2 <- matrix(1, nrow = 3, ncol = 3)
  rho3 <- 1
  C3 <- matrix(1)
  rho4 <- n(c(2, 1))
  C4 <- matrix(1, nrow = 2, ncol = 2)
  g_hsbm7 <- sample_hierarchical_sbm(
    21,
    m = c(3, 10, 5, 3),
    rho = list(rho1, rho2, rho3, rho4),
    C = list(C1, C2, C3, C4),
    p = 0
  )
  expect_true(is_simple(g_hsbm7))

  g_hsbm8 <- sample_hierarchical_sbm(
    21,
    m = c(3, 10, 5, 3),
    rho = list(rho1, rho2, rho3, rho4),
    C = list(C1, C2, C3, C4),
    p = 1
  )
  expect_equal(g_hsbm5[] + g_hsbm7[], g_hsbm8[])
})`

const rtdal003027Source0035 = `test_that("Dot product rng works", {
  withr::local_seed(42)
  vecs <- cbind(
    c(0, 1, 1, 1, 0) / 3,
    c(0, 1, 1, 0, 1) / 3,
    c(1, 1, 1, 1, 0) / 4,
    c(0, 1, 1, 1, 0)
  )

  g <- sample_dot_product(vecs)
  g0 <- graph_from_literal(1:2:3 - 4)
  expect_equal(as.matrix(g[]), as.matrix(g0[]), ignore_attr = TRUE)

  vecs <- replicate(5, rep(1 / 2, 4))
  g <- sample_dot_product(vecs)
  expect_equal(g[], make_full_graph(5)[], ignore_attr = TRUE)

  g2 <- sample_dot_product(vecs, directed = TRUE)
  expect_equal(g2[], make_full_graph(5, directed = TRUE)[], ignore_attr = TRUE)

  vecs <- replicate(100, rep(sqrt(1 / 8), 4))
  g <- sample_dot_product(vecs)
  expect_ecount(g, 2451)

  g2 <- sample_dot_product(vecs, directed = TRUE)
  expect_ecount(g2, 4941)
})`

const rtdal003027Source0036 = `test_that("sample_dot_product generates edges with correct probabilities", {
  withr::local_seed(42)
  latent_features <- cbind(
    c(0, 1, 1, 1, 0) / 3,
    c(0, 1, 1, 0, 1) / 3,
    c(1, 1, 1, 1, 0) / 4,
    c(0, 1, 1, 1, 0)
  )
  expected_probs <- t(latent_features) %*% latent_features
  diag(expected_probs) <- 0
  num_graphs <- 1000
  edge_counts <- matrix(0, nrow = 4, ncol = 4)

  for (i in seq_len(num_graphs)) {
    g <- sample_dot_product(latent_features)
    adj_matrix <- as_adjacency_matrix(g, sparse = FALSE)
    edge_counts <- edge_counts + adj_matrix
  }
  empirical_probs <- edge_counts / num_graphs
  diag(empirical_probs) <- 0
  tolerance <- 0.05
  expect_true(all(abs(empirical_probs - expected_probs) < tolerance))
})`

const rtdal003027Source0037 = `test_that("Dot product rng gives warnings", {
  withr::local_seed(42)
  vecs <- cbind(c(1, 1, 1) / 3, -c(1, 1, 1) / 3)
  expect_warning(
    g <- sample_dot_product(vecs),
    "Negative connection probability in dot-product graph"
  )

  vecs <- cbind(c(1, 1, 1), c(1, 1, 1))
  expect_warning(
    g <- sample_dot_product(vecs),
    paste0("Greater than 1 connection probability ", "in dot-product graph")
  )
})`

