const rtdal003028Source0002 = `test_that("Graphlets work for some simple graphs", {
  full <- make_full_graph(5)
  E(full)$weight <- 1
  full_glet <- graphlet_basis(full)

  expect_equal(names(full_glet), c("cliques", "thresholds"))
  expect_equal(length(full_glet$cliques), 1)
  expect_equal(sort(full_glet$cliques[[1]]), V(full)[seq_len(vcount(full))])
  expect_equal(full_glet$thresholds, 1)

  E(full)[1 %--% 2]$weight <- 2
  full_glet2 <- sortgl(graphlet_basis(full))

  expect_equal(
    full_glet2,
    list(
      cliques = lapply(
        list(1:2, 1:5),
        unsafe_create_vs,
        graph = full,
        verts = V(full)
      ),
      thresholds = c(2, 1)
    )
  )
})`

const rtdal003028Source0003 = `test_that("Graphlets filtering works", {
  df <- data.frame(
    from = c("A", "A", "B", "B", "B", "C", "C", "D"),
    to = c("B", "C", "C", "D", "E", "D", "E", "E"),
    weight = c(8, 8, 8, 5, 5, 5, 5, 5)
  )

  g <- graph_from_data_frame(
    df,
    directed = FALSE,
    vertices = data.frame(LETTERS[1:5])
  )
  glet <- sortgl(graphlet_basis(g))

  expect_equal(unvs(glet$cliques), list(1:3, 2:5))
  expect_equal(glet$thresholds, c(8, 5))
})`

const rtdal003028Source0005 = `graphlets.old <- function(graph) {
  if (!is_weighted(graph)) {
    cli::cli_abort("Graph not weighted")
  }
  if (min(E(graph)$weight) <= 0 || any(!is.finite(E(graph)$weight))) {
    cli::cli_abort("Edge weights must be non-negative and finite")
  }

  ## Do all thresholds
  cl <- lapply(sort(unique(E(graph)$weight)), function(w) {
    threshold.net(graph, w)
  })

  ## Put the cliques in one long list
  clv <- unlist(cl, recursive = FALSE)

  ## Sort the vertices within the cliques
  cls <- lapply(clv, sort)

  ## Delete duplicate cliques
  clu <- unique(cls)

  ## Delete cliques that consist of single vertices
  clf <- clu[sapply(clu, length) != 1]

  clf
}`

const rtdal003028Source0006 = `test_that("Graphlets work for a bigger graph", {
  withr::local_seed(42)
  g <- make_graph("zachary")
  E(g)$weight <- sample(1:5, ecount(g), replace = TRUE)

  gl <- graphlet_basis(g)
  gl2 <- graphlets.old(g)

  glo <- sort(sapply(unvs(gl$cliques), paste, collapse = "-"))
  gl2o <- sort(sapply(gl2, paste, collapse = "-"))

  expect_equal(glo, gl2o)
})`

const rtdal003028Source0007 = "graphlets.project.old <- function(graph, cliques, iter, Mu = NULL) {\n  if (!is_weighted(graph)) {\n    cli::cli_abort(\"Graph not weighted\")\n  }\n  if (min(E(graph)$weight) <= 0 || any(!is.finite(E(graph)$weight))) {\n    cli::cli_abort(\"Edge weights must be non-negative and finite\")\n  }\n  if (\n    length(iter) != 1 ||\n      !is.numeric(iter) ||\n      !is.finite(iter) ||\n      iter != as.integer(iter)\n  ) {\n    cli::cli_abort(\"`iter' must be a non-negative finite integer scalar\")\n  }\n\n  clf <- cliques\n\n  ## Create vertex-clique list first\n  vcl <- vector(length = vcount(graph), mode = \"list\")\n  for (i in 1:length(clf)) {\n    for (j in clf[[i]]) {\n      vcl[[j]] <- c(vcl[[j]], i)\n    }\n  }\n\n  ## Create edge-clique list from this, it is useful to have the edge list\n  ## of the graph at hand\n  el <- as_edgelist(graph, names = FALSE)\n  ecl <- vector(length = ecount(graph), mode = \"list\")\n  for (i in 1:ecount(graph)) {\n    edge <- el[i, ]\n    ecl[[i]] <- intersect(vcl[[edge[1]]], vcl[[edge[2]]])\n  }\n\n  ## We will also need a clique-edge list, the edges in the cliques\n  system.time({\n    cel <- vector(length = length(clf), mode = \"list\")\n    for (i in 1:length(ecl)) {\n      for (j in ecl[[i]]) {\n        cel[[j]] <- c(cel[[j]], i)\n      }\n    }\n  })\n\n  ## OK, we are ready to do the projection now\n  if (is.null(Mu)) {\n    Mu <- rep(1, length(clf))\n  }\n  origw <- E(graph)$weight\n  w <- numeric(length(ecl))\n  a <- sapply(clf, function(x) length(x) * (length(x) + 1) / 2)\n  for (i in 1:iter) {\n    for (j in 1:length(ecl)) {\n      w[j] <- sum(Mu[ecl[[j]]])\n    }\n    for (j in 1:length(clf)) {\n      Mu[j] <- Mu[j] * sum(origw[cel[[j]]] / (w[cel[[j]]] + .0001)) / a[j]\n    }\n  }\n\n  ## Sort the cliques according to their weights\n  Smb <- sort(Mu, decreasing = TRUE, index.return = TRUE)\n  list(cliques = clf[Smb$ix], Mu = Mu[Smb$ix])\n}"

const rtdal003028Source0008 = `test_that("Graphlet projection works", {
  D1 <- matrix(0, 5, 5)
  D2 <- matrix(0, 5, 5)
  D3 <- matrix(0, 5, 5)
  D1[1:3, 1:3] <- 2
  D2[3:5, 3:5] <- 3
  D3[2:5, 2:5] <- 1
  g <- graph_from_adjacency_matrix(
    D1 + D2 + D3,
    mode = "undirected",
    weighted = TRUE
  )
  g <- simplify(g)

  gl <- graphlet_basis(g)
  glp <- graphlets(g)
  glp2 <- graphlets.project.old(g, cliques = gl$cliques, iter = 1000)

  expect_equal(glp, glp2)
})`

