const rtdal003037Source0003 = `test_that("sample_motifs works", {
  withr::local_seed(20041103)

  g <- make_graph(~ A - B - C - A - D - E - F - D - C - F)
  n <- vcount(g)

  motif_count <- sample_motifs(g)
  expect_true(0 <= motif_count && motif_count <= n * (n - 1) * (n - 2) / 6)

  motif_count_letters <- sample_motifs(g, sample = c("C", "D", "E", "F"))
  expect_true(
    0 <= motif_count_letters && motif_count_letters <= n * (n - 1) * (n - 2) / 6
  )

  motif_count_all <- sample_motifs(g, sample = V(g))
  expect_true(
    0 <= motif_count_all && motif_count_all <= n * (n - 1) * (n - 2) / 6
  )
})`

const rtdal003037Source0004 = `test_that("dyad_census works", {
  g1 <- make_ring(10)
  expect_warning(dc1 <- dyad_census(g1), "directed")
  expect_equal(dc1, list(mut = 10, asym = 0, null = 35))

  g2 <- make_ring(10, directed = TRUE, mutual = TRUE)
  dc2 <- dyad_census(g2)
  expect_equal(dc2, list(mut = 10, asym = 0, null = 35))

  g3 <- make_ring(10, directed = TRUE, mutual = FALSE)
  dc3 <- dyad_census(g3)
  expect_equal(dc3, list(mut = 0, asym = 10, null = 35))
})`

const rtdal003037Source0005 = `test_that("dyad_census works with celegansneural", {
  ce <- simplify(read_graph(gzfile("celegansneural.gml.gz"), format = "gml"))
  dc <- dyad_census(ce)

  expect_equal(dc, list(mut = 197, asym = 1951, null = 41808))
  expect_equal(sum(which_mutual(ce)), dc$mut * 2)
  expect_equal(
    ecount(as_undirected(ce, mode = "collapse")) - dc$mut,
    dc$asym
  )
  expect_equal(sum(unlist(dc)), vcount(ce) * (vcount(ce) - 1) / 2)
})`

const rtdal003037Source0006 = `test_that("motifs with callback works", {
  withr::local_seed(123)

  g <- make_graph(~ A - B - C - A - D - E - F - D - C - F)

  # Count motifs using callback
  count <- 0
  isoclasses <- integer(0)

  motifs(g, 3, callback = function(vids, isoclass) {
    count <<- count + 1
    isoclasses <<- c(isoclasses, isoclass)
    FALSE # continue search
  })

  expect_true(count > 0)
  expect_true(all(isoclasses >= 1))
  expect_true(all(isoclasses <= 16)) # max isoclass for size 3
})`

const rtdal003037Source0007 = `test_that("motifs with callback can stop early", {
  withr::local_seed(123)

  g <- make_graph(~ A - B - C - A - D - E - F - D - C - F)

  # Stop after finding 3 motifs
  count <- 0

  motifs(g, 3, callback = function(vids, isoclass) {
    count <<- count + 1
    if (count >= 3) {
      TRUE # stop after 3 motifs
    } else {
      FALSE # continue
    }
  })

  expect_equal(count, 3)
})`

const rtdal003037Source0008 = `test_that("motifs with callback receives correct arguments", {
  withr::local_seed(123)

  g <- make_graph(~ A - B - C - A)

  # Check argument types
  motifs(g, 3, callback = function(vids, isoclass) {
    expect_true(is.integer(vids))
    expect_equal(length(vids), 3)
    expect_true(is.integer(isoclass))
    expect_equal(length(isoclass), 1)
    TRUE # stop after first motif
  })
})`

const rtdal003037Source0009 = `test_that("motifs with callback handles errors in callback", {
  withr::local_seed(123)

  g <- make_graph(~ A - B - C - A - D - E - F - D - C - F)

  # Callback that throws an error
  expect_error(
    motifs(g, 3, callback = function(vids, isoclass) {
      stop("Intentional error in callback")
    }),
    "Error in R callback function"
  )
})`

const rtdal003037Source0010 = `test_that("motifs with callback output matches expected", {
  withr::local_seed(42)

  g <- make_graph(~ A - B - C - A - D - E - F - D - C - F)

  # Collect motif information
  motif_data <- list()
  motifs(g, 3, callback = function(vids, isoclass) {
    motif_data[[length(motif_data) + 1]] <<- list(
      vids = vids,
      isoclass = isoclass
    )
    FALSE # Continue
  })

  # Snapshot test for motif structure
  expect_snapshot({
    cat("Number of motifs found:", length(motif_data), "\n")
    motif_data[1:2]
  })
})`

