const rtdal003054Source0004 = `test_that("degree() works", {
  gnp1 <- sample_gnp(100, 1 / 100)
  gnp1_deg <- degree(gnp1)
  el <- as_edgelist(gnp1)
  expect_equal(as.numeric(table(el)), gnp1_deg[gnp1_deg != 0])

  expect_equal(gnp1_deg / (vcount(gnp1) - 1), degree(gnp1, normalized = TRUE))

  gnp2 <- sample_gnp(100, 2 / 100, directed = TRUE)
  gnp2_deg_in <- degree(gnp2, mode = "in")
  el2 <- as_edgelist(gnp2)
  expect_equal(as.numeric(table(el2[, 2])), gnp2_deg_in[gnp2_deg_in != 0])

  gnp2_deg_out <- degree(gnp2, mode = "out")
  expect_equal(as.numeric(table(el2[, 1])), gnp2_deg_out[gnp2_deg_out != 0])

  expect_equal(
    gnp2_deg_in / (vcount(gnp2) - 1),
    degree(gnp2, mode = "in", normalized = TRUE)
  )
  expect_equal(
    gnp2_deg_out / (vcount(gnp2) - 1),
    degree(gnp2, mode = "out", normalized = TRUE)
  )
  expect_equal(
    degree(gnp2, mode = "all") / (vcount(gnp2) - 1),
    degree(gnp2, mode = "all", normalized = TRUE)
  )
})`

const rtdal003054Source0005 = `test_that("max_degree() works", {
  g <- make_graph(c(1, 2, 2, 2, 2, 3), directed = TRUE)
  expect_equal(max_degree(g), 4)
  expect_equal(max_degree(g, mode = "out"), 2)
  expect_equal(max_degree(g, loops = FALSE), 2)
  expect_equal(max_degree(g, mode = "out", loops = FALSE), 1)
  expect_equal(max_degree(g, mode = "in", loops = FALSE), 1)
  expect_equal(max_degree(g, v = c()), 0)
  expect_equal(max_degree(make_empty_graph()), 0)
})`

const rtdal003054Source0006 = `test_that("mean_degree() works", {
  # Undirected graph: formula is 2 * edges / vertices
  g_undirected <- make_ring(10)
  expect_equal(mean_degree(g_undirected), 2)

  # Directed graph: formula is edges / vertices
  # This graph has edges 1->2, 2->2 (loop), 2->3, so 3 edges / 3 vertices = 1
  g_directed <- make_graph(c(1, 2, 2, 2, 2, 3), directed = TRUE)
  expect_equal(mean_degree(g_directed), 1)

  # Test loops parameter: excluding the self-loop (2->2)
  # Without loops: (3 edges - 1 loop) / 3 vertices = 2/3
  expect_equal(mean_degree(g_directed, loops = FALSE), 2 / 3)

  # Empty graph
  expect_true(is.nan(mean_degree(make_empty_graph())))

  # Compare with manual calculation for undirected graph
  g_random <- sample_gnp(100, 0.05)
  manual_mean <- 2 * ecount(g_random) / vcount(g_random)
  expect_equal(mean_degree(g_random), manual_mean)

  # For directed graph
  g_directed_random <- sample_gnp(100, 0.05, directed = TRUE)
  manual_mean_dir <- ecount(g_directed_random) / vcount(g_directed_random)
  expect_equal(mean_degree(g_directed_random), manual_mean_dir)
})`

